function sourceNorm(v){return String(v||'').trim().toLowerCase().replace(/[+]/g,'plus').replace(/[\s._-]+/g,'')}
function sourceFor(v){const n=sourceNorm(v);if(!n)return null;return WATCH_SOURCES.find(s=>sourceNorm(s.id)===n||sourceNorm(s.name)===n||(s.aliases||[]).some(a=>sourceNorm(a)===n))||null}
function sourceCanonical(v){const raw=String(v||'').trim(),s=sourceFor(raw);return s?s.name:raw}
function sourceBadge(v,mode='compact'){const raw=String(v||'').trim();if(!raw)return '';const s=sourceFor(raw),name=s?.name||raw;if(!s)return `<span class="watchSourceBadge custom ${mode}" title="${esc(name)}"><span>${esc(name)}</span></span>`;return `<span class="watchSourceBadge ${mode} source-${s.id}" title="${esc(name)}"><img src="${esc(s.logo)}" alt="${esc(name)}" referrerpolicy="no-referrer" onerror="this.style.display='none';this.nextElementSibling.classList.remove('srOnly');this.nextElementSibling.classList.add('sourceFallbackText')"><span class="srOnly">${esc(name)}</span></span>`}
function selectedWorkSourceValue(){const other=$('#workPlatformOther');if(other&&!other.classList.contains('hidden'))return String(other.value||'').trim();return sourceCanonical($('#workPlatform')?.value||'')}
function renderWorkSourcePicker(kind,selected=''){let current=sourceCanonical(selected),match=sourceFor(current),allowed=WATCH_SOURCES.filter(s=>s.kinds.includes(kind));if(match&&!allowed.some(s=>s.id===match.id)){current='';match=null}const picker=$('#workSourcePicker'),other=$('#workPlatformOther'),label=$('#workSourceLabel'),hint=$('#workSourceHint');if(!picker)return;if(label)label.innerHTML=kind==='series'?'منصة المسلسل <span>اختياري</span>':'مكان المشاهدة / المصدر <span>اختياري</span>';if(hint)hint.textContent=kind==='series'?'اختر منصة المسلسل. سيظهر شعارها بشكل أنيق في البطاقة.':'اختر السينما أو القناة أو منصة البث التي شاهدت الفيلم عبرها.';const isCustom=!!current&&!match;picker.innerHTML=`<button type="button" class="sourceChoice ${!current?'active':''}" data-source="">بدون مصدر</button>`+allowed.map(s=>`<button type="button" class="sourceChoice source-${s.id} ${match?.id===s.id?'active':''}" data-source="${s.id}" title="${esc(s.name)}"><img src="${esc(s.logo)}" alt="${esc(s.name)}" referrerpolicy="no-referrer" onerror="this.style.display='none'"><span>${esc(s.name)}</span></button>`).join('')+`<button type="button" class="sourceChoice ${isCustom?'active':''}" data-source="other">أخرى</button>`;if($('#workPlatform'))$('#workPlatform').value=match?.name||current;if(other){other.classList.toggle('hidden',!isCustom);other.value=isCustom?current:'';other.oninput=()=>{$('#workPlatform').value=other.value.trim()}};$$('#workSourcePicker .sourceChoice').forEach(b=>b.onclick=()=>{const key=b.dataset.source;if(key==='other'){if($('#workPlatform'))$('#workPlatform').value='';if(other){other.classList.remove('hidden');other.value='';other.focus()}$$('#workSourcePicker .sourceChoice').forEach(x=>x.classList.toggle('active',x===b));return}if(other){other.classList.add('hidden');other.value=''};const s=WATCH_SOURCES.find(x=>x.id===key);if($('#workPlatform'))$('#workPlatform').value=s?.name||'';$$('#workSourcePicker .sourceChoice').forEach(x=>x.classList.toggle('active',x===b))})}

function normalizeGenre(v){const s=String(v||'').trim().replace(/\s+/g,' ');const aliases={'اكشن':'أكشن','أكشن':'أكشن','خيال علمى':'خيال علمي','خيال علمي':'خيال علمي','رومانسي':'رومانسي','رومانسية':'رومانسي','انيمي':'أنيمي','أنمي':'أنيمي','أنيمي':'أنيمي'};return aliases[s]||s}
function workGenres(w){const raw=Array.isArray(w?.genres)&&w.genres.length?w.genres:String(w?.genre||'').split(/[،,]/);return [...new Set(raw.map(normalizeGenre).filter(Boolean))]}
function workGenreText(w){return workGenres(w).join(' • ')}
function selectedWorkGenres(){return $$('#workGenres .genreChoice.active').map(b=>b.dataset.genre).filter(Boolean)}
function renderWorkGenrePicker(selected=[]){const chosen=[...new Set((selected||[]).map(normalizeGenre).filter(Boolean))],all=[...GENRES,...chosen.filter(g=>!GENRES.includes(g))];$('#workGenres').innerHTML=all.map(g=>`<button type="button" class="genreChoice ${chosen.includes(g)?'active':''}" data-genre="${esc(g)}">${esc(g)}</button>`).join('');$$('#workGenres .genreChoice').forEach(b=>b.onclick=()=>{b.classList.toggle('active');updateGenrePickerSummary()});updateGenrePickerSummary()}
function updateGenrePickerSummary(){const a=selectedWorkGenres(),el=$('#workGenreSummary');if(el)el.textContent=a.length?`${a.length} تصنيف محدد: ${a.join('، ')}`:'اختر تصنيفًا واحدًا على الأقل'}
