function fmtRating(v){const n=Number(v);if(!Number.isFinite(n))return '—';const rounded=Math.round(n*10)/10;return Number.isInteger(rounded)?String(rounded):rounded.toFixed(1)}
function seasonsText(v){const n=Number(v);if(!Number.isFinite(n)||n<1)return '';if(n===1)return 'موسم واحد';if(n===2)return 'موسمان';return `${n} مواسم`}
function viewingSeasonCount(v){const n=Number(v?.seasons_watched??v?.season_number);return Number.isFinite(n)&&n>0?n:null}
function seriesRatingContext(v){const n=viewingSeasonCount(v);return n?`بعد ${seasonsText(n)}`:''}

