function seed(){const now=new Date().toISOString(),profiles=[{id:'admin-1',username:'admin',public_slug:'admin-cinema',display_name:'مالك كادر',bio:'إدارة المنصة',avatar_url:'',role:'admin',is_active:true,created_at:now,password:'admin'},{id:'user-1',username:'abdullah',public_slug:'abdullah-cinema',display_name:'عبدالله',bio:'أشارك الأفلام والمسلسلات التي تستحق وقتك من وجهة نظري 🎬',avatar_url:'',role:'creator',is_active:true,created_at:now,password:'user'}];const works=[{id:'w1',owner_id:'user-1',title:'Dune: Part Two',kind:'movie',genre:'خيال علمي',genres:['خيال علمي'],release_year:2024,platform:'Cinema',poster_url:'',notes:'تجربة بصرية وصوتية ضخمة، بناء العالم ممتاز والإخراج واثق جدًا.',rating_override:null,status:'completed',created_at:'2026-08-18T10:00:00Z',updated_at:now},{id:'w2',owner_id:'user-1',title:'Shōgun',kind:'series',genre:'دراما',genres:['دراما'],release_year:2024,platform:'Disney+',poster_url:'',notes:'كتابة هادئة وناضجة مع تمثيل قوي وتصوير ممتاز.',rating_override:9.6,status:'completed',created_at:'2026-08-16T10:00:00Z',updated_at:now}];const viewings=[{id:'v1',work_id:'w1',owner_id:'user-1',watched_at:'2026-08-18T10:00:00Z',season_number:null,episode_number:null,status:'completed',notes:'المشاهدة الأولى',created_at:now,updated_at:now},{id:'v2',work_id:'w2',owner_id:'user-1',watched_at:'2026-08-16T10:00:00Z',season_number:1,episode_number:10,status:'completed',notes:'نهاية الموسم',created_at:now,updated_at:now}];const vals={v1:[10,9,10,10,10,10],v2:[10,10,9,10,9,10]},ratings=[];viewings.forEach(v=>CRITERIA.forEach(([criterion],i)=>ratings.push({id:uid(),work_id:v.work_id,viewing_id:v.id,owner_id:v.owner_id,criterion,rating:vals[v.id][i],notes:'',created_at:now,updated_at:now})));return{profiles,works,viewings,ratings,watchlist:[]}}
function localLoad(){let d;try{d=JSON.parse(localStorage.getItem(LOCAL_STORE)||'null')}catch{}if(!d){d=seed();localStorage.setItem(LOCAL_STORE,JSON.stringify(d))}if(!d.kadrV14Migrated){(d.works||[]).forEach(w=>{w.genres=workGenres(w);if(w.rating_override!==null&&w.rating_override!==undefined&&Number(w.rating_override)<=5)w.rating_override=Math.round(Number(w.rating_override)*20)/10});(d.viewings||[]).forEach(v=>{if(v.overall_rating!==null&&v.overall_rating!==undefined&&Number(v.overall_rating)<=5)v.overall_rating=Math.round(Number(v.overall_rating)*20)/10});(d.ratings||[]).forEach(r=>{if(Number(r.rating)<=5)r.rating=Math.round(Number(r.rating)*20)/10});d.kadrV14Migrated=true;localStorage.setItem(LOCAL_STORE,JSON.stringify(d))}if(!d.kadrV16Migrated){(d.viewings||[]).forEach(v=>{if((v.seasons_watched===null||v.seasons_watched===undefined)&&v.season_number)v.seasons_watched=Number(v.season_number)});d.kadrV16Migrated=true;localStorage.setItem(LOCAL_STORE,JSON.stringify(d))}state.profiles=d.profiles||[];state.works=d.works||[];state.viewings=d.viewings||[];state.ratings=d.ratings||[];state.watchlist=d.watchlist||[];const sid=localStorage.getItem(LOCAL_SESSION)||sessionStorage.getItem(LOCAL_SESSION);state.currentProfile=sid?state.profiles.find(p=>p.id===sid&&p.is_active!==false)||null:null;state.session=state.currentProfile}
