function releaseBusy(btn,busy,label='جارٍ التنفيذ…'){if(!btn)return;if(busy){btn.dataset.prevText=btn.textContent;btn.disabled=true;btn.classList.add('releaseBusy');btn.textContent=label}else{btn.disabled=false;btn.classList.remove('releaseBusy');if(btn.dataset.prevText){btn.textContent=btn.dataset.prevText;delete btn.dataset.prevText}}}
async function refreshReleaseState(){if(!CLOUD_READY)return state.release;const {data,error}=await sb.from('mashhad_app_release').select('*').eq('id','main').maybeSingle();if(error)throw error;if(data)state.release=data;refreshReleaseUI();return state.release}
async function waitForReleaseState(test,timeout=10000){const started=Date.now();let last=state.release;while(Date.now()-started<timeout){last=await refreshReleaseState();if(test(last))return last;await new Promise(r=>setTimeout(r,350))}return last}
async function clearKadrShellCaches(){try{if('caches'in window){const keys=await caches.keys();await Promise.all(keys.filter(k=>k.startsWith('kadr-shell-')).map(k=>caches.delete(k)))}}catch(e){console.warn(e)}}
async function clearKadrNotifications(){try{if('serviceWorker'in navigator){const reg=await navigator.serviceWorker.ready;const notes=await reg.getNotifications();notes.forEach(n=>{const tag=String(n.tag||'').toLowerCase(),title=String(n.title||'');if(!tag||tag.includes('kadr')||tag.includes('update')||/كادر|KADR/i.test(title))n.close()})}}catch(e){console.warn(e)}}
async function activateFreshShell(){await clearKadrShellCaches();try{if('serviceWorker'in navigator){const reg=await navigator.serviceWorker.getRegistration();if(reg){await reg.update();if(reg.waiting)reg.waiting.postMessage({type:'SKIP_WAITING'});await new Promise(r=>setTimeout(r,350))}}}catch(e){console.warn(e)}}
