async function refreshApp(){const b=$('#refreshBtn');if(b?.classList.contains('refreshing'))return;b?.classList.add('refreshing');try{if(CLOUD_READY)await loadCloud();else{localLoad();route()}toast('تم تحديث البيانات فقط — لم يتم تثبيت أي تحديث')}catch(e){console.error(e);toast('تعذر تحديث البيانات')}finally{setTimeout(()=>b?.classList.remove('refreshing'),700)}}
async function init(){startLiveClock();setupInstallExperience();registerAppServiceWorker();const remember=$('#rememberMe');if(remember)remember.checked=localStorage.getItem(REMEMBER_KEY)!=='0';if(CLOUD_READY){await loadCloud();setTimeout(syncExistingPushSubscription,500);setTimeout(refreshTmdbStatus,650);if(isAdmin()&&candidateMode()&&state.release?.candidate_status==='testing'&&!state.release?.candidate_tested_at)setTimeout(()=>markCandidateTested({silent:true}),220);sb.auth.onAuthStateChange(()=>setTimeout(loadCloud,80));['mashhad_profiles','mashhad_works','mashhad_viewings','mashhad_ratings'].forEach(t=>sb.channel('rt-'+t).on('postgres_changes',{event:'*',schema:'public',table:t},()=>loadCloud()).subscribe());sb.channel('rt-kadr-watchlist').on('postgres_changes',{event:'*',schema:'public',table:'mashhad_watchlist'},()=>reloadWatchlist()).subscribe();sb.channel('rt-kadr-follows').on('postgres_changes',{event:'*',schema:'public',table:'mashhad_follows'},()=>reloadSocialState()).subscribe();sb.channel('rt-kadr-social-notifications').on('postgres_changes',{event:'*',schema:'public',table:'mashhad_social_notifications'},payload=>{reloadSocialState();if(payload.eventType==='INSERT')toast('🔔 '+String(payload.new?.title||'إشعار جديد من شخص تتابعه'))}).subscribe();if(isAdmin())sb.channel('rt-kadr-signup-requests').on('postgres_changes',{event:'*',schema:'public',table:'mashhad_signup_requests'},payload=>{reloadSignupRequests();if(payload.eventType==='INSERT')toast('🆕 طلب حساب جديد في KADR')}).subscribe();sb.channel('rt-mashhad-release').on('postgres_changes',{event:'UPDATE',schema:'public',table:'mashhad_app_release'},payload=>{state.release=payload.new||state.release;refreshReleaseUI();if(isAdmin()&&candidateMode()&&state.release?.candidate_status==='testing'&&!state.release?.candidate_tested_at)setTimeout(()=>markCandidateTested({silent:true}),160);const info=pendingUpdateInfo();if(info)notifyUpdateOnce(info)}).subscribe()}else{localLoad();route()}$('#demoNote')?.classList.toggle('hidden',CLOUD_READY);if($('#brandSub'))$('#brandSub').innerHTML=`<span style="display:inline-flex;align-items:center;gap:5px"><span style="width:6px;height:6px;border-radius:50%;background:${CLOUD_READY?'#62b98c':'#d5b24a'}"></span>${CLOUD_READY?'متزامن مباشر':'نسخة محلية'}</span>`;await syncPushPermissionUI()}

function setRoute(params={}){const u=new URL(location.href);u.search='';Object.entries(params).forEach(([k,v])=>v!==undefined&&u.searchParams.set(k,v));history.pushState({},'',u);route()}window.onpopstate=route;
function route(){refreshReleaseUI();const q=new URLSearchParams(location.search),shared=PROXY_SHARE_SLUG||q.get('share'),wantsAdmin=q.get('admin')==='1',wantsDash=q.get('dashboard')==='1',workTarget=q.get('work');if(!state.currentProfile){document.body.classList.remove('shareMode');state.viewProfile=null;return renderLanding()}document.body.classList.toggle('shareMode',!!shared);if(shared){state.viewProfile=state.profiles.find(x=>String(x.public_slug||'').toLowerCase()===String(shared).toLowerCase()&&x.is_active!==false&&x.approval_status!=='pending'&&x.approval_status!=='rejected')||null;renderPublic();return maybeOpenWorkTarget(workTarget)}if(wantsAdmin&&isAdmin())return renderAdmin();if(wantsDash)return renderDashboard();const requested=q.get('u');const username=(requested||state.currentProfile.username||'').toLowerCase();state.viewProfile=state.profiles.find(p=>p.username?.toLowerCase()===username&&p.is_active!==false&&p.approval_status!=='pending'&&p.approval_status!=='rejected')||null;renderPublic();maybeOpenWorkTarget(workTarget)}
function maybeOpenWorkTarget(id){if(!id)return;const w=state.works.find(x=>String(x.id)===String(id));if(!w||!state.viewProfile||w.owner_id!==state.viewProfile.id)return;setTimeout(()=>{openDetail(w.id);const u=new URL(location.href);u.searchParams.delete('work');history.replaceState({},'',u)},80)}
function renderLanding(){$('#publicView').classList.remove('hidden');$('#dashboardView').classList.add('hidden');$('#adminView').classList.add('hidden');$('#catalogSection').classList.add('hidden');$('#addWorkHomeBtn')?.classList.add('hidden');$('#communityBtn')?.classList.add('hidden');$('#settingsBtn')?.classList.add('hidden');$('#profileHero').innerHTML=`<div class="accessGate"><div class="accessGateMark">K</div><div class="badge">🔒 للأعضاء المعتمدين فقط</div><h1>مرحبًا بك في KADR</h1><p class="lead">لا يمكن تصفح التقييمات أو صفحات المستخدمين بدون حساب. إذا كنت تملك حسابًا معتمدًا فسجّل الدخول، أو أرسل طلب انضمام جديد إلى المالك.</p><div class="accessGateActions"><button class="btn primary" onclick="openAuth()">تسجيل الدخول</button><button class="btn secondary" onclick="openSignupRequest()">طلب حساب جديد</button></div><div class="accessGateFlow"><span><b>1</b> أنشئ طلبك</span><span><b>2</b> موافقة المالك</span><span><b>3</b> دخول كامل إلى KADR</span></div></div>`;$('#genreFilters').innerHTML='';$('#workGrid').innerHTML=''}
function renderPublic(){const pv=$('#publicView');pv.classList.remove('hidden');$('#dashboardView').classList.add('hidden');$('#adminView').classList.add('hidden');$('#catalogSection').classList.remove('hidden');const p=state.viewProfile,addBtn=$('#addWorkHomeBtn');if(!p){addBtn?.classList.add('hidden');$('#profileHero').innerHTML=`<div class="empty"><h2 style="color:var(--text)">هذه الصفحة غير متاحة</h2><p>قد يكون الرابط غير صحيح أو الحساب غير منشور.</p></div>`;$('#workGrid').innerHTML='';return}const ownPage=!!state.currentProfile&&state.currentProfile.id===p.id&&!isShareMode();addBtn?.classList.toggle('hidden',!ownPage);const works=profileWorks(p.id),avg=avgOf(works);$('#profileHero').innerHTML=`<div class="profiletop"><img class="avatar" src="${esc(p.avatar_url||avatarPlaceholder(p.display_name))}" onerror="this.src='${avatarPlaceholder(p.display_name)}'"><div class="profileinfo"><h1>${esc(p.display_name)}</h1><div class="handle">@${esc(p.username)}</div></div></div>${p.bio?`<p class="bio">${esc(p.bio)}</p>`:''}<div class="profileactions"><button class="btn secondary" onclick="shareProfile('${esc(p.id)}')">↗ مشاركة الصفحة</button>${ownPage?`<button class="btn primary" onclick="setRoute({dashboard:'1'})">لوحة تحكمي</button><button class="btn secondary" onclick="openCommunity('discover')">👥 المجتمع</button>`:state.currentProfile?followActionsHtml(p):''}</div><div class="stats"><div class="stat"><b>${works.length}</b><span>كل الأعمال</span></div><div class="stat"><b>${works.filter(w=>w.kind==='movie').length}</b><span>أفلام</span></div><div class="stat"><b>${works.filter(w=>w.kind==='series').length}</b><span>مسلسلات</span></div><div class="stat"><b>${avg?fmtRating(avg):'—'}</b><span>متوسط التقييم /10</span></div></div>`;renderFilters(works,false);renderPublicGrid()}
function renderFilters(works,dash){const target=dash?'#dashGenreFilters':'#genreFilters',key=dash?'dashGenre':'genre',genres=[...new Set(works.flatMap(workGenres).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ar'));if(state[key]!=='all'&&!genres.includes(state[key]))state[key]='all';$(target).innerHTML=`<button class="chip ${state[key]==='all'?'active':''}" data-genre="all">كل التصنيفات</button>`+genres.map(g=>`<button class="chip ${state[key]===g?'active':''}" data-genre="${esc(g)}">${esc(g)}</button>`).join('');$$(target+' .chip').forEach(b=>b.onclick=()=>{state[key]=b.dataset.genre;renderFilters(works,dash);dash?renderDashboardGrid():renderPublicGrid()})}
function filteredWorks(list,type,genre,query){const q=String(query||'').trim().toLowerCase();return list.filter(w=>w.kind===type&&(genre==='all'||workGenres(w).includes(genre))&&(!q||[w.title,workGenreText(w),sourceCanonical(w.platform),w.notes].some(v=>String(v||'').toLowerCase().includes(q)))).sort((a,b)=>finalRating(b)-finalRating(a)||new Date(b.updated_at)-new Date(a.updated_at))}
function workCard(w,editable=false){const r=finalRating(w),views=workViewings(w.id),latest=views[0],seasonCtx=w.kind==='series'&&viewingSeasonCount(latest)?`<span>•</span><span>${esc(seasonsText(viewingSeasonCount(latest)))}</span>`:'';return `<article class="work" data-id="${w.id}"><div class="poster"><img src="${esc(w.poster_url||posterPlaceholder(w.title,w.kind))}" onerror="this.src='${posterPlaceholder(w.title,w.kind)}'"><div class="posterbadges"><span class="typepill">${typeIcon(w.kind)} ${typeName(w.kind)} · ${esc(statusName(w.status))}</span><span class="score"><b>${r?fmtRating(r):'—'}</b>${r?'<small class="scoreStar" aria-hidden="true">★</small>':''}</span></div></div><div class="workbody"><h3>${esc(w.title)}</h3><div class="meta"><span>${esc(workGenreText(w))}</span><span>•</span><span>${w.release_year||'—'}</span>${w.platform?`<span>•</span>${sourceBadge(w.platform,'compact')}`:''}${seasonCtx}<span>•</span><span>${views.length} مشاهدة</span></div>${w.notes?`<div class="reviewline">${esc(w.notes)}</div>`:''}${editable?`<div class="inlineactions" style="margin-top:10px"><button class="btn secondary" onclick="event.stopPropagation();openWorkForm(state.works.find(x=>x.id==='${w.id}'))">تعديل</button><button class="btn secondary" onclick="event.stopPropagation();openViewingForm('${w.id}')">＋ مشاهدة</button><button class="btn danger" onclick="event.stopPropagation();deleteWork('${w.id}')">حذف</button></div>`:''}</div></article>`}
function bindWorkCards(sel){$$(sel+' .work').forEach(c=>c.onclick=()=>openDetail(c.dataset.id))}
function renderPublicGrid(){const p=state.viewProfile;if(!p)return;const list=filteredWorks(profileWorks(p.id),state.type,state.genre,state.search);$$('#typeSegment button').forEach(b=>b.classList.toggle('active',b.dataset.type===state.type));$('#listTitle').textContent=`${typePlural(state.type)} الأعلى تقييمًا`;$('#workGrid').innerHTML=list.length?list.map(w=>workCard(w)).join(''):`<div class="empty">لا توجد تقييمات في هذا القسم حتى الآن.</div>`;bindWorkCards('#workGrid')}

let pendingWatchlistConvert=null;
function ownWatchlist(){const id=state.currentProfile?.id;return state.watchlist.filter(x=>x.owner_id===id).sort((a,b)=>Number(a.sort_order||0)-Number(b.sort_order||0)||new Date(a.created_at)-new Date(b.created_at))}
function watchlistSourceOptions(kind,selected=''){const current=sourceCanonical(selected),allowed=WATCH_SOURCES.filter(s=>s.kinds.includes(kind));return `<option value="">بدون تحديد</option>`+allowed.map(s=>`<option value="${esc(s.name)}" ${current===s.name?'selected':''}>${esc(s.name)}</option>`).join('')}
function renderWatchlistPreview(){const box=$('#watchlistPreview');if(!box)return;const list=ownWatchlist();if(!list.length){box.innerHTML=`<button class="watchlistEmpty" onclick="openWatchlistItemForm()"><span>＋</span><b>ابدأ قائمتك القادمة</b><small>أضف أول فيلم أو مسلسل تريد مشاهدته.</small></button>`;return}box.innerHTML=list.slice(0,4).map((item,i)=>`<button class="watchlistMini" onclick="openWatchlist()"><span class="watchlistRank">${i+1}</span><img src="${esc(item.poster_url||posterPlaceholder(item.title,item.kind))}" onerror="this.src='${posterPlaceholder(item.title,item.kind)}'"><span class="watchlistMiniText"><b>${esc(item.title)}${item.season_number?` · الموسم ${item.season_number}`:''}</b><small>${typeIcon(item.kind)} ${typeName(item.kind)}${item.release_year?` · ${item.release_year}`:''}${item.platform?` · ${esc(sourceCanonical(item.platform))}`:''}${item.linked_work_id?' · مرتبط بتقييماتك السابقة':''}</small></span>${i===0?'<em>التالي</em>':''}</button>`).join('')+(list.length>4?`<button class="watchlistMore" onclick="openWatchlist()">+${list.length-4} أخرى</button>`:'')}
function watchlistCard(item,index,total){return `<article class="watchlistItem"><div class="watchlistRank large">${index+1}</div><img class="watchlistPoster" src="${esc(item.poster_url||posterPlaceholder(item.title,item.kind))}" onerror="this.src='${posterPlaceholder(item.title,item.kind)}'"><div class="watchlistItemBody"><div class="watchlistTitleRow"><h3>${esc(item.title)}${item.season_number?` <span class="seasonInline">الموسم ${item.season_number}</span>`:''}</h3>${index===0?'<span class="nextBadge">التالي</span>':''}</div><div class="watchlistMeta"><span>${typeIcon(item.kind)} ${typeName(item.kind)}</span>${item.release_year?`<span>• ${item.release_year}</span>`:''}${item.platform?`<span>•</span>${sourceBadge(item.platform,'compact')}`:''}${item.linked_work_id?`<span class="linkedSeasonBadge">↗ ضمن سجل المسلسل</span>`:''}</div>${item.notes?`<p>${esc(item.notes)}</p>`:''}<div class="watchlistItemActions"><button class="btn primary compactBtn" onclick="convertWatchlistToRating('${item.id}')">${item.linked_work_id&&item.season_number?'★ قيّم الموسم':'✓ حوّل إلى تقييم'}</button><button class="btn secondary compactBtn" onclick="openWatchlistItemForm(state.watchlist.find(x=>x.id==='${item.id}'))">تعديل</button><button class="btn ghost orderBtn" ${index===0?'disabled':''} onclick="moveWatchlistItem('${item.id}',-1)">↑</button><button class="btn ghost orderBtn" ${index===total-1?'disabled':''} onclick="moveWatchlistItem('${item.id}',1)">↓</button><button class="btn danger compactBtn" onclick="deleteWatchlistItem('${item.id}')">حذف</button></div></div></article>`}
function renderWatchlistFull(){const list=ownWatchlist(),box=$('#watchlistFull'),sum=$('#watchlistSummary');if(sum){const movies=list.filter(x=>x.kind==='movie').length,series=list.length-movies;sum.innerHTML=`<div><b>${list.length}</b><span>في القائمة</span></div><div><b>${movies}</b><span>أفلام</span></div><div><b>${series}</b><span>مسلسلات</span></div>`}if(!box)return;box.innerHTML=list.length?list.map((x,i)=>watchlistCard(x,i,list.length)).join(''):`<div class="watchlistFullEmpty"><span>🎞️</span><h3>قائمتك فارغة</h3><p>أضف الأعمال التي تريد مشاهدتها ورتبها حسب الأولوية.</p><button class="btn primary" onclick="openWatchlistItemForm()">＋ إضافة أول عمل</button></div>`}
function openWatchlist(){if(!state.currentProfile)return openAuth();renderWatchlistFull();show('watchlistModal')}
function refreshWatchlistPlatformOptions(selected=''){const kind=$('#watchlistKind')?.value||'movie',el=$('#watchlistPlatform');if(el)el.innerHTML=watchlistSourceOptions(kind,selected)}
function openWatchlistItemForm(item=null){if(!state.currentProfile)return openAuth();$('#watchlistItemTitle').textContent=item?'تعديل عنصر في قائمتي':'إضافة لقائمتي القادمة';$('#watchlistId').value=item?.id||'';$('#watchlistTmdbId').value=item?.tmdb_id||'';$('#watchlistTmdbType').value=item?.tmdb_media_type||'';$('#watchlistPosterRemote').value=item?.poster_url||'';$('#watchlistLinkedWorkId').value=item?.linked_work_id||'';$('#watchlistTitle').value=item?.title||'';$('#watchlistTitle').readOnly=false;$('#watchlistKind').disabled=false;$('#watchlistKind').value=item?.kind||'movie';$('#watchlistYear').value=item?.release_year||'';$('#watchlistSeason').value=item?.season_number||'';$('#watchlistNotes').value=item?.notes||'';populateWatchlistLinkedSeries(item?.linked_work_id||'');refreshWatchlistSeriesFields();if(item?.linked_work_id){$('#watchlistLinkedSeries').value=item.linked_work_id;applyWatchlistLinkedSeries(item.linked_work_id);$('#watchlistSeason').value=item?.season_number||$('#watchlistSeason').value;$('#watchlistTmdbId').value=item?.tmdb_id||$('#watchlistTmdbId').value;$('#watchlistTmdbType').value=item?.tmdb_media_type||$('#watchlistTmdbType').value;$('#watchlistPosterRemote').value=item?.poster_url||$('#watchlistPosterRemote').value}refreshWatchlistPlatformOptions(item?.platform||'');$('#watchlistPoster').value='';const img=$('#watchlistPreviewImage');if(img){img.style.display=item?.poster_url?'block':'none';img.src=item?.poster_url||''}$('#watchlistTmdbPosterNote')?.classList.toggle('hidden',!item?.tmdb_id);hide('watchlistModal');show('watchlistItemModal')}
async function reloadWatchlist(){if(!CLOUD_READY||!state.currentProfile){state.watchlist=[];renderWatchlistPreview();return}const {data,error}=await sb.from('mashhad_watchlist').select('*').order('sort_order',{ascending:true}).order('created_at',{ascending:true});if(error){console.warn(error);return}state.watchlist=data||[];renderWatchlistPreview();if($('#watchlistModal')?.classList.contains('show'))renderWatchlistFull()}
async function saveWatchlistItem(){if(!state.currentProfile)return;const id=$('#watchlistId').value,item=state.watchlist.find(x=>x.id===id),title=$('#watchlistTitle').value.trim();if(!title)return toast('أدخل اسم الفيلم أو المسلسل');const btn=$('#saveWatchlistBtn');btn.disabled=true;try{const f=$('#watchlistPoster').files?.[0],remotePoster=$('#watchlistPosterRemote').value.trim(),poster=f?await uploadMedia(f,'watchlist',900,1350):(remotePoster||item?.poster_url||''),kind=$('#watchlistKind').value,linked=$('#watchlistLinkedWorkId').value||null,season=kind==='series'&&$('#watchlistSeason').value?Number($('#watchlistSeason').value):null,payload={title,kind,release_year:$('#watchlistYear').value?Number($('#watchlistYear').value):null,platform:$('#watchlistPlatform').value||'',poster_url:poster,notes:$('#watchlistNotes').value.trim(),linked_work_id:linked,season_number:season,tmdb_id:$('#watchlistTmdbId').value?Number($('#watchlistTmdbId').value):null,tmdb_media_type:$('#watchlistTmdbType').value||null};if(linked){const w=state.works.find(x=>x.id===linked&&x.owner_id===state.currentProfile.id&&x.kind==='series');if(!w)throw new Error('INVALID_LINKED_SERIES');if(!season){btn.disabled=false;return toast('حدد رقم الموسم الجديد')}const watched=maxSeriesSeason(w.id);if(season<=watched&&!confirm(`لديك تقييم مسجل حتى الموسم ${watched}. هل تريد إضافة الموسم ${season} للقائمة رغم ذلك؟`)){btn.disabled=false;return}}if(CLOUD_READY){if(linked&&payload.tmdb_id){const linkedWork=state.works.find(x=>x.id===linked);if(linkedWork&&!linkedWork.tmdb_id){const {error:te}=await sb.from('mashhad_works').update({tmdb_id:payload.tmdb_id,tmdb_media_type:payload.tmdb_media_type||'tv'}).eq('id',linked);if(te)throw te}}if(id){const {error}=await sb.from('mashhad_watchlist').update(payload).eq('id',id);if(error)throw error}else{const list=ownWatchlist(),last=Math.max(0,...list.map(x=>Number(x.sort_order)||0));const {error}=await sb.from('mashhad_watchlist').insert({...payload,owner_id:state.currentProfile.id,sort_order:last+1000});if(error)throw error}await reloadWatchlist()}else{const now=new Date().toISOString();if(linked&&payload.tmdb_id){const linkedWork=state.works.find(x=>x.id===linked);if(linkedWork&&!linkedWork.tmdb_id){linkedWork.tmdb_id=payload.tmdb_id;linkedWork.tmdb_media_type=payload.tmdb_media_type||'tv'}}if(item)Object.assign(item,payload,{updated_at:now});else state.watchlist.push({id:uid(),owner_id:state.currentProfile.id,...payload,sort_order:(ownWatchlist().at(-1)?.sort_order||0)+1000,created_at:now,updated_at:now});localSave();renderWatchlistPreview()}hide('watchlistItemModal');openWatchlist();toast(id?'تم تحديث القائمة':linked&&season?`تمت إضافة الموسم ${season} إلى قائمتك`:'تمت الإضافة إلى قائمتك القادمة')}catch(e){console.error(e);toast('تعذر حفظ العنصر')}finally{btn.disabled=false}}
async function deleteWatchlistItem(id,silent=false){const item=state.watchlist.find(x=>x.id===id&&x.owner_id===state.currentProfile?.id);if(!item)return false;if(!silent&&!confirm(`حذف «${item.title}» من قائمتك القادمة؟`))return false;try{if(CLOUD_READY){const {error}=await sb.from('mashhad_watchlist').delete().eq('id',id);if(error)throw error;await reloadWatchlist()}else{state.watchlist=state.watchlist.filter(x=>x.id!==id);localSave();renderWatchlistPreview();renderWatchlistFull()}if(!silent)toast('تم الحذف من القائمة');return true}catch(e){console.error(e);if(!silent)toast('تعذر حذف العنصر');return false}}
async function moveWatchlistItem(id,delta){const list=ownWatchlist(),i=list.findIndex(x=>x.id===id),j=i+delta;if(i<0||j<0||j>=list.length)return;const a=list[i],b=list[j],ao=Number(a.sort_order)||((i+1)*1000),bo=Number(b.sort_order)||((j+1)*1000);try{if(CLOUD_READY){const [ra,rb]=await Promise.all([sb.from('mashhad_watchlist').update({sort_order:bo}).eq('id',a.id),sb.from('mashhad_watchlist').update({sort_order:ao}).eq('id',b.id)]);if(ra.error||rb.error)throw ra.error||rb.error;await reloadWatchlist()}else{a.sort_order=bo;b.sort_order=ao;localSave();renderWatchlistPreview();renderWatchlistFull()}}catch(e){console.error(e);toast('تعذر تغيير الترتيب')}}
function convertWatchlistToRating(id){const item=state.watchlist.find(x=>x.id===id&&x.owner_id===state.currentProfile?.id);if(!item)return;hide('watchlistModal');if(item.linked_work_id&&item.kind==='series'){const w=state.works.find(x=>x.id===item.linked_work_id&&x.owner_id===state.currentProfile?.id);if(w)return openViewingForm(w.id,null,item)}openWorkForm(null,item)}
function renderDashboard(){const p=state.currentProfile;if(!p)return;$('#publicView').classList.add('hidden');$('#dashboardView').classList.remove('hidden');$('#adminView').classList.add('hidden');const works=profileWorks(p.id),avg=avgOf(works),views=state.viewings.filter(v=>v.owner_id===p.id).length;$('#dashboardHero').innerHTML=`<h1>مرحبًا ${esc(p.display_name)} 👋</h1><p class="lead">هذه مساحتك الخاصة لإدارة تقييماتك وسجل مشاهداتك. صفحتك متاحة لأعضاء KADR المسجلين للقراءة فقط.</p><div class="quickActions"><button class="quickAction" onclick="setRoute({})"><span class="qicon">👁</span><span>صفحتي الرسمية<small>الواجهة التي يراها أعضاء KADR</small></span></button><button class="quickAction" onclick="openWatchlist()"><span class="qicon">☰</span><span>قائمتي القادمة<small>خاصة بك فقط · ${ownWatchlist().length} عناصر</small></span></button><button class="quickAction" onclick="openProfileForm()"><span class="qicon">✎</span><span>تعديل ملفي<small>الاسم والصورة والنبذة</small></span></button>${isAdmin()?`<button class="quickAction" onclick="setRoute({admin:'1'})"><span class="qicon">⚙</span><span>إدارة المنصة<small>المستخدمون والتحديثات</small></span></button>`:''}</div><div class="dashboardShare"><div class="label">رابطي في كادر</div><div class="row"><input readonly value="${esc(visualShareUrl(p))}"><button class="btn secondary" onclick="copyProfile('${esc(p.id)}')">نسخ</button></div></div><div class="cards"><div class="metric"><b>${works.length}</b><span>كل الأعمال</span></div><div class="metric"><b>${views}</b><span>المشاهدات</span></div><div class="metric"><b>${works.filter(w=>w.kind==='series').length}</b><span>مسلسلات</span></div><div class="metric"><b>${avg?fmtRating(avg):'—'}</b><span>متوسط التقييم /10</span></div></div>`;renderFilters(works,true);renderDashboardGrid();renderWatchlistPreview()}
function renderDashboardGrid(){const p=state.currentProfile;if(!p)return;const list=filteredWorks(profileWorks(p.id),state.dashType,state.dashGenre,state.dashSearch);$$('#dashTypeSegment button').forEach(b=>b.classList.toggle('active',b.dataset.type===state.dashType));$('#dashGrid').innerHTML=list.length?list.map(w=>workCard(w,true)).join(''):`<div class="empty">لا توجد أعمال في هذا القسم حتى الآن.</div>`;bindWorkCards('#dashGrid')}
function releaseAdminCard(){const r=state.release||{},status=r.candidate_status||'idle',sha=String(r.candidate_git_sha||'').slice(0,8);if(r.candidate_available&&status==='testing'){const tested=!!r.candidate_tested_at;if(!candidateMode())return `<div class="releaseCard"><div class="releaseRow"><div><span class="previewBadge">${r.candidate_files_verified?'✓ GitHub موثّق':'⏳ قيد التحقق'} · بانتظار اختبار المالك</span><h3 style="font-size:25px;margin:8px 0">v${esc(r.candidate_version)}</h3></div><button class="btn primary" onclick="openCandidateBuild()">فتح النسخة التجريبية</button></div><p>الإصدار الحالي للمستخدمين: <b>v${esc(r.stable_version)}</b>${sha?`<br>بصمة الملفات: <span dir="ltr">${esc(sha)}</span>`:''}<br>${esc(r.candidate_notes||'')}</p></div>`;if(!tested)return `<div class="releaseCard"><div class="releaseRow"><div><span class="previewBadge">✓ النسخة مفتوحة للمالك · جاهزة للاعتماد</span><h3 style="font-size:25px;margin:8px 0">v${esc(r.candidate_version)}</h3></div><button class="btn primary" onclick="approveCandidateRelease(this)">✓ اعتماد ونشر</button></div><p>ضغطة واحدة فقط: إذا كان تأكيد الاختبار لم يصل للخادم بعد، يثبته KADR تلقائيًا ثم يعيد التحقق من نفس الملفات وينشر الإصدار.</p></div>`;return `<div class="releaseCard"><div class="releaseRow"><div><span class="previewBadge">✓ تم الاختبار · جاهز للاعتماد</span><h3 style="font-size:25px;margin:8px 0">v${esc(r.candidate_version)}</h3></div><button class="btn primary" onclick="approveCandidateRelease(this)">✓ اعتماد ونشر</button></div><p>ضغطة واحدة فقط: يعيد KADR التحقق من نفس الملفات التي اختبرتها، ثم يعتمد الإصدار وينشره للمستخدمين إذا لم تتغير.</p></div>`}if(r.candidate_available&&status==='approved_waiting_publish'){return `<div class="releaseCard"><div class="releaseRow"><div><span class="previewBadge">✓ معتمد من المدير · جارٍ النشر التلقائي</span><h3 style="font-size:25px;margin:8px 0">v${esc(r.candidate_version)}</h3></div><span class="releaseSpinner" aria-label="جارٍ النشر"></span></div><p>لا تحتاج لأي ضغطة إضافية. سيقوم KADR بترقية نفس ملفات النسخة التي اختبرتها ثم يتحقق منها قبل إرسالها للمستخدمين.</p></div>`}return `<div class="releaseCard"><div class="releaseRow"><div><span class="previewBadge">✓ الإصدار المنشور</span><h3 style="font-size:25px;margin:8px 0">v${esc(r.stable_version||visibleVersion())}</h3></div><button class="btn secondary" onclick="openReleaseForm()">＋ تهيئة تحديث</button></div><p>يرصد KADR candidate.json ومجلد الإصدار المنفصل تلقائيًا. تبقى النسخة الجديدة معزولة عن المستخدمين حتى يختبرها المالك ويعتمدها بضغطة واحدة.</p></div>`}
function renderSignupRequests(){const section=$('#signupRequestsSection'),list=$('#signupRequestsList'),count=$('#signupRequestsCount');if(!section||!list)return;const rows=(state.signupRequests||[]).filter(r=>r.status!=='approved').sort((a,b)=>(a.status==='pending'?0:1)-(b.status==='pending'?0:1)||new Date(b.requested_at)-new Date(a.requested_at));const pending=rows.filter(r=>r.status==='pending').length;if(count)count.textContent=String(pending);section.classList.toggle('hidden',rows.length===0);list.innerHTML=rows.map(r=>`<article class="signupRequestCard ${r.status}"><div class="signupRequestIdentity"><div class="requestAvatar">${esc(String(r.display_name||'K').charAt(0))}</div><div><b>${esc(r.display_name)}</b><span dir="ltr">@${esc(r.username)}</span><small dir="ltr">${esc(r.email)}</small></div></div><div class="signupRequestMeta"><span class="requestStatus ${r.status}">${r.status==='pending'?'بانتظار موافقتك':'مرفوض'}</span><small>${dateTimeAr(r.requested_at)}</small></div><div class="signupRequestActions"><button class="btn primary compactBtn" onclick="approveSignupRequest('${r.id}',this)">${r.status==='pending'?'✓ موافقة':'✓ اعتماد الآن'}</button>${r.status==='pending'?`<button class="btn danger compactBtn" onclick="rejectSignupRequest('${r.id}',this)">رفض</button>`:''}</div></article>`).join('')}
function renderAdmin(){if(!isAdmin())return setRoute({});$('#publicView').classList.add('hidden');$('#dashboardView').classList.add('hidden');$('#adminView').classList.remove('hidden');const users=state.profiles.filter(p=>p.role!=='admin'&&p.approval_status!=='pending'&&p.approval_status!=='rejected'),pending=(state.signupRequests||[]).filter(r=>r.status==='pending').length;$('#adminHero').innerHTML=`<h1>إدارة كادر</h1><p class="lead">إدارة طلبات الانضمام والمستخدمين وإصدارات التطبيق بنظام المالك أولًا.</p><div class="cards"><div class="metric requestMetric"><b>${pending}</b><span>طلبات تنتظر الموافقة</span></div><div class="metric"><b>${users.filter(x=>x.is_active).length}</b><span>مستخدم نشط</span></div><div class="metric"><b>${state.works.length}</b><span>تقييمات</span></div><div class="metric"><b>${state.viewings.length}</b><span>مشاهدات</span></div></div><div style="margin-top:14px">${releaseAdminCard()}</div>`;renderSignupRequests();$('#usersTable').innerHTML=users.length?users.map(p=>`<tr><td><b>${esc(p.display_name)}</b><div class="hint">@${esc(p.username)}</div></td><td><span dir="ltr">${esc(visualShareUrl(p))}</span></td><td>${profileWorks(p.id).length}</td><td><span class="status ${p.is_active?'onstatus':'offstatus'}">${p.is_active?'نشط':'موقوف'}</span></td><td>${dateAr(p.created_at)}</td><td><div class="inlineactions"><button class="btn secondary" onclick="setRoute({u:'${esc(p.username)}'})">عرض</button><button class="btn secondary" onclick="toggleUser('${p.id}',${!p.is_active})">${p.is_active?'إيقاف':'تفعيل'}</button><button class="btn ghost" onclick="openResetPassword('${p.id}')">كلمة المرور</button></div></td></tr>`).join(''):`<tr><td colspan="6">لا يوجد مستخدمون معتمدون بعد.</td></tr>`}
async function reloadSignupRequests(){if(!CLOUD_READY||!isAdmin())return;const {data,error}=await sb.from('mashhad_signup_requests').select('*').order('requested_at',{ascending:false}).limit(100);if(error){console.warn(error);return}state.signupRequests=data||[];if(!$('#adminView').classList.contains('hidden'))renderSignupRequests()}
async function signupAdminAction(action,requestId,btn=null){if(!isAdmin()||!CLOUD_READY)return;const session=(await sb.auth.getSession()).data.session;if(!session)return;const prev=btn?.textContent;if(btn){btn.disabled=true;btn.textContent='جارٍ التنفيذ…'}try{const r=await fetch(SIGNUP_ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json','apikey':SUPABASE_KEY,'Authorization':`Bearer ${session.access_token}`},body:JSON.stringify({action,request_id:requestId})}),data=await r.json().catch(()=>({}));if(!r.ok||!data.ok)throw new Error(data.error||'REQUEST_FAILED');await loadCloud();if(!$('#adminView').classList.contains('hidden'))renderAdmin();toast(action==='approve'?'✓ تم اعتماد الحساب ويمكنه الدخول الآن':'تم رفض طلب الحساب')}catch(e){console.error(e);toast('تعذر تحديث طلب الحساب')}finally{if(btn){btn.disabled=false;btn.textContent=prev}}}
function approveSignupRequest(id,btn){return signupAdminAction('approve',id,btn)}
function rejectSignupRequest(id,btn){if(!confirm('رفض طلب هذا الحساب؟ لن يستطيع الدخول ما لم تعتمد الطلب لاحقًا.'))return;return signupAdminAction('reject',id,btn)}

function openAuth(){hide('signupRequestModal');$('#accountPendingNote')?.classList.add('hidden');$('#accountRejectedNote')?.classList.add('hidden');show('authModal')}
function openSignupRequest(){hide('authModal');$('#signupRequestSuccess')?.classList.add('hidden');$$('#signupRequestModal .formgrid, #signupRequestModal .signupPolicy, #signupRequestModal .formactions').forEach(x=>x.classList.remove('hidden'));show('signupRequestModal')}
async function submitSignupRequest(){if(!CLOUD_READY)return toast('طلبات الحسابات تحتاج اتصال KADR بالخادم');const display_name=$('#signupDisplayName').value.trim(),username=$('#signupUsername').value.trim().toLowerCase(),email=$('#signupEmail').value.trim().toLowerCase(),password=$('#signupPassword').value,confirmPassword=$('#signupPasswordConfirm').value,website=$('#signupWebsite').value;if(display_name.length<2)return toast('أدخل اسمًا ظاهرًا صحيحًا');if(!/^[a-z0-9_]{3,24}$/.test(username))return toast('اليوزر 3–24 حرفًا: a-z و0-9 و_ فقط');if(!email||!email.includes('@'))return toast('أدخل بريدًا إلكترونيًا صحيحًا');if(password.length<8)return toast('كلمة المرور 8 أحرف على الأقل');if(password!==confirmPassword)return toast('تأكيد كلمة المرور غير مطابق');const btn=$('#submitSignupRequestBtn');btn.disabled=true;const prev=btn.textContent;btn.textContent='جارٍ إرسال الطلب…';try{const r=await fetch(SIGNUP_ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json','apikey':SUPABASE_KEY},body:JSON.stringify({action:'request',display_name,username,email,password,website})}),data=await r.json().catch(()=>({}));if(!r.ok||!data.ok){const map={USERNAME_TAKEN:'اسم المستخدم مستخدم بالفعل',EMAIL_TAKEN:'البريد الإلكتروني مرتبط بحساب موجود',INVALID_USERNAME:'اسم المستخدم غير صالح',INVALID_EMAIL:'البريد الإلكتروني غير صالح',WEAK_PASSWORD:'كلمة المرور يجب أن تكون 8 أحرف على الأقل',REQUEST_EXISTS:data.status==='pending'?'لديك طلب موجود بانتظار موافقة المالك':data.status==='rejected'?'طلب سابق بهذا اليوزر أو البريد تم رفضه؛ تواصل مع المالك':'يوجد حساب أو طلب سابق بهذه البيانات'};return toast(map[data.error]||'تعذر إرسال طلب الحساب')}$$('#signupRequestModal .formgrid, #signupRequestModal .signupPolicy, #signupRequestModal .formactions').forEach(x=>x.classList.add('hidden'));$('#signupRequestSuccess')?.classList.remove('hidden');toast('✓ تم إرسال طلب الحساب للمالك')}catch(e){console.error(e);toast('تعذر إرسال الطلب الآن')}finally{btn.disabled=false;btn.textContent=prev}}
async function login(){const identifier=$('#loginIdentifier').value.trim(),password=$('#loginPassword').value;if(!identifier||!password)return toast('أدخل اسم المستخدم وكلمة المرور');localStorage.setItem(REMEMBER_KEY,$('#rememberMe').checked?'1':'0');const btn=$('#loginBtn');btn.disabled=true;$('#accountPendingNote')?.classList.add('hidden');$('#accountRejectedNote')?.classList.add('hidden');try{if(CLOUD_READY){const r=await fetch(LOGIN_ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json','apikey':SUPABASE_KEY},body:JSON.stringify({identifier,password,action:'login'})}),data=await r.json().catch(()=>({}));if(!r.ok||!data.ok){if(data.code==='EMAIL_NOT_CONFIRMED')$('#confirmNote').classList.remove('hidden');if(data.code==='ACCOUNT_PENDING')$('#accountPendingNote')?.classList.remove('hidden');if(data.code==='ACCOUNT_REJECTED')$('#accountRejectedNote')?.classList.remove('hidden');const msg=data.code==='ACCOUNT_PENDING'?'طلب حسابك بانتظار موافقة مالك KADR':data.code==='ACCOUNT_REJECTED'?'تم رفض طلب الحساب':data.code==='ACCOUNT_DISABLED'?'الحساب موقوف':data.code==='NOT_MASHHAD_USER'?'هذا الحساب غير مفعل في KADR':'بيانات الدخول غير صحيحة';return toast(msg)}await sb.auth.setSession({access_token:data.session.access_token,refresh_token:data.session.refresh_token});hide('authModal');await loadCloud();toast('تم تسجيل الدخول')}else{const p=state.profiles.find(x=>x.username.toLowerCase()===identifier.toLowerCase()&&x.password===password);if(!p)return toast('بيانات الدخول غير صحيحة');const storage=$('#rememberMe').checked?localStorage:sessionStorage;localStorage.removeItem(LOCAL_SESSION);sessionStorage.removeItem(LOCAL_SESSION);storage.setItem(LOCAL_SESSION,p.id);state.currentProfile=p;hide('authModal');route();toast('تم تسجيل الدخول')}}catch(e){console.error(e);toast('تعذر تسجيل الدخول')}finally{btn.disabled=false}}
async function resendConfirmation(){const identifier=$('#loginIdentifier').value.trim();if(!identifier)return toast('أدخل اسم المستخدم أو البريد');try{const r=await fetch(LOGIN_ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json','apikey':SUPABASE_KEY},body:JSON.stringify({identifier,action:'resend'})});if(!r.ok)throw new Error();toast('تم إرسال رابط التأكيد إن كان الحساب يحتاجه')}catch{toast('تعذر إرسال رابط التأكيد')}}
async function logout(){if(CLOUD_READY)await sb.auth.signOut();else{localStorage.removeItem(LOCAL_SESSION);sessionStorage.removeItem(LOCAL_SESSION)}state.currentProfile=null;state.session=null;hide('settingsModal');setRoute({});toast('تم تسجيل الخروج')}


let tmdbSearchTarget='work',tmdbSearchResults=[],pendingWatchlistViewingConvert=null;
async function tmdbCall(body){if(!CLOUD_READY||!TMDB_ENDPOINT)throw Object.assign(new Error('TMDB_UNAVAILABLE'),{code:'TMDB_UNAVAILABLE'});const session=(await sb.auth.getSession()).data.session;if(!session)throw Object.assign(new Error('NO_SESSION'),{code:'NO_SESSION'});const r=await fetch(TMDB_ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json','apikey':SUPABASE_KEY,'Authorization':`Bearer ${session.access_token}`},body:JSON.stringify(body)}),data=await r.json().catch(()=>({}));if(!r.ok||!data.ok){const e=new Error(data.detail||data.error||'TMDB_REQUEST_FAILED');e.code=data.error||'TMDB_REQUEST_FAILED';throw e}return data}
async function refreshTmdbStatus(){if(!state.currentProfile||!CLOUD_READY)return;try{const data=await tmdbCall({action:'status'});state.tmdbConfigured=!!data.configured;const badge=$('#tmdbStatusBadge');if(badge){badge.textContent=data.configured?'✓ متصل':'غير مربوط';badge.classList.toggle('connected',!!data.configured)}$('#tmdbOwnerConfig')?.classList.toggle('hidden',!isAdmin())}catch(e){console.warn(e);const badge=$('#tmdbStatusBadge');if(badge)badge.textContent='تعذر التحقق'}}
async function saveTmdbToken(){if(!isAdmin())return;const token=$('#tmdbTokenInput')?.value.trim();if(!token)return toast('الصق API Read Access Token من TMDB');const btn=$('#saveTmdbTokenBtn');btn.disabled=true;const old=btn.textContent;btn.textContent='جارٍ التحقق…';try{await tmdbCall({action:'configure',token});$('#tmdbTokenInput').value='';state.tmdbConfigured=true;await refreshTmdbStatus();toast('✓ تم ربط TMDB بنجاح')}catch(e){console.error(e);toast(e.code==='INVALID_TOKEN'?'TMDB token غير صحيح':'تعذر ربط TMDB')}finally{btn.disabled=false;btn.textContent=old}}
function targetTitleForTmdb(){return tmdbSearchTarget==='watchlist'?$('#watchlistTitle')?.value:$('#workTitle')?.value}
function openTmdbSearch(target='work'){if(!state.currentProfile)return openAuth();tmdbSearchTarget=target;tmdbSearchResults=[];$('#tmdbSearchResults').innerHTML='';$('#tmdbSearchState').textContent=state.tmdbConfigured?'اكتب اسم العمل للبحث.':'إذا لم يكن TMDB مربوطًا بعد، يمكن للمالك ربطه من الإعدادات.';const preset=String(targetTitleForTmdb()||'').trim();$('#tmdbSearchInput').value=preset;$('#tmdbKindFilter').value=target==='watchlist'?($('#watchlistKind')?.value||'all'):($('#workKind')?.value||'all');show('tmdbSearchModal');setTimeout(()=>{$('#tmdbSearchInput')?.focus();if(preset.length>=2)runTmdbSearch()},120)}
async function runTmdbSearch(){const q=$('#tmdbSearchInput').value.trim(),kind=$('#tmdbKindFilter').value;if(q.length<2)return toast('اكتب حرفين على الأقل');const btn=$('#tmdbSearchSubmitBtn'),stateBox=$('#tmdbSearchState');btn.disabled=true;stateBox.textContent='جارٍ البحث في TMDB…';$('#tmdbSearchResults').innerHTML='';try{const data=await tmdbCall({action:'search',query:q,kind});tmdbSearchResults=data.results||[];state.tmdbConfigured=true;if(!tmdbSearchResults.length){stateBox.textContent='لم أجد نتائج مطابقة. جرّب الاسم الإنجليزي أو سنة مختلفة.';return}stateBox.textContent=`${tmdbSearchResults.length} نتيجة — اختر النتيجة الصحيحة`;$('#tmdbSearchResults').innerHTML=tmdbSearchResults.map((r,i)=>`<button class="tmdbResult" data-tmdb-index="${i}"><img src="${esc(r.poster_url||posterPlaceholder(r.title,r.kind))}" onerror="this.src='${posterPlaceholder(r.title,r.kind)}'"><span><b>${esc(r.title)}</b><small>${r.kind==='series'?'📺 مسلسل':'🎬 فيلم'}${r.year?` · ${r.year}`:''}</small>${r.original_title&&r.original_title!==r.title?`<em>${esc(r.original_title)}</em>`:''}${r.overview?`<p>${esc(r.overview)}</p>`:''}</span><strong>اختيار</strong></button>`).join('')}catch(e){console.error(e);stateBox.textContent=e.code==='TMDB_NOT_CONFIGURED'?'TMDB غير مربوط بعد. افتح الإعدادات بحساب المالك وأدخل API Read Access Token.':e.code==='TMDB_AUTH_FAILED'?'انتهت صلاحية ربط TMDB. يحتاج المالك لإعادة إدخال Token.':'تعذر البحث في TMDB الآن.'}finally{btn.disabled=false}}
function setTmdbPoster(target,url){const remote=$(target==='work'?'#workPosterRemote':'#watchlistPosterRemote'),img=$(target==='work'?'#workPreview':'#watchlistPreviewImage'),note=$(target==='work'?'#workTmdbPosterNote':'#watchlistTmdbPosterNote');if(remote)remote.value=url||'';if(img&&url){img.src=url;img.style.display='block'}if(note)note.classList.toggle('hidden',!url)}
function chooseTmdbResult(index){const r=tmdbSearchResults[Number(index)];if(!r)return;if(tmdbSearchTarget==='work'){$('#workTitle').value=r.title;$('#workKind').value=r.kind;$('#workYear').value=r.year||'';$('#workTmdbId').value=r.tmdb_id||'';$('#workTmdbType').value=r.tmdb_media_type||'';setTmdbPoster('work',r.poster_url_high||r.poster_url||'');toggleSeriesFields(r.kind,'.seriesOnly');renderWorkSourcePicker(r.kind,selectedWorkSourceValue())}else{const linked=$('#watchlistLinkedWorkId').value;if(!linked){$('#watchlistTitle').value=r.title;$('#watchlistKind').value=r.kind;$('#watchlistYear').value=r.year||''}else if(!$('#watchlistYear').value&&r.year)$('#watchlistYear').value=r.year;$('#watchlistTmdbId').value=r.tmdb_id||'';$('#watchlistTmdbType').value=r.tmdb_media_type||'';setTmdbPoster('watchlist',r.poster_url_high||r.poster_url||'');refreshWatchlistSeriesFields();refreshWatchlistPlatformOptions($('#watchlistPlatform').value)}hide('tmdbSearchModal');toast('✓ تم اختيار بيانات TMDB')}
function ownSeriesWorks(){const id=state.currentProfile?.id;return state.works.filter(w=>w.owner_id===id&&w.kind==='series').sort((a,b)=>String(a.title).localeCompare(String(b.title),'ar'))}
function maxSeriesSeason(workId){return Math.max(0,...state.viewings.filter(v=>v.work_id===workId).map(v=>Number(viewingSeasonCount(v)||0)))}
function populateWatchlistLinkedSeries(selected=''){const el=$('#watchlistLinkedSeries');if(!el)return;const works=ownSeriesWorks();el.innerHTML=`<option value="">لا — مسلسل جديد</option>`+works.map(w=>`<option value="${esc(w.id)}" ${String(selected)===String(w.id)?'selected':''}>${esc(w.title)}${maxSeriesSeason(w.id)?` — شاهدت ${maxSeriesSeason(w.id)} موسم`:''}</option>`).join('')}
function refreshWatchlistSeriesFields(){const series=$('#watchlistKind')?.value==='series';$$('.watchlistSeriesOnly').forEach(x=>x.classList.toggle('hidden',!series));if(series)populateWatchlistLinkedSeries($('#watchlistLinkedWorkId')?.value||'');else{$('#watchlistLinkedWorkId').value='';$('#watchlistSeason').value=''}}
function applyWatchlistLinkedSeries(id){const w=state.works.find(x=>x.id===id&&x.owner_id===state.currentProfile?.id&&x.kind==='series');$('#watchlistLinkedWorkId').value=w?.id||'';const title=$('#watchlistTitle'),kind=$('#watchlistKind');if(w){title.value=w.title;title.readOnly=true;kind.value='series';kind.disabled=true;$('#watchlistYear').value=w.release_year||'';$('#watchlistPlatform').value=sourceCanonical(w.platform||'');$('#watchlistTmdbId').value=w.tmdb_id||'';$('#watchlistTmdbType').value=w.tmdb_media_type||'tv';setTmdbPoster('watchlist',w.poster_url||'');const next=maxSeriesSeason(w.id)+1;if(!$('#watchlistSeason').value)$('#watchlistSeason').value=next}else{title.readOnly=false;kind.disabled=false}refreshWatchlistPlatformOptions($('#watchlistPlatform').value);refreshWatchlistSeriesFields()}
async function fetchWatchlistSeasonPoster(){if($('#watchlistKind').value!=='series')return;const tmdbId=Number($('#watchlistTmdbId').value),season=Number($('#watchlistSeason').value);if(!tmdbId)return toast('اربط المسلسل بنتيجة TMDB أولًا عبر زر البحث');if(!Number.isInteger(season)||season<1)return toast('حدد رقم الموسم');const btn=$('#watchlistSeasonPosterBtn');btn.disabled=true;try{const data=await tmdbCall({action:'season',tmdb_id:tmdbId,season_number:season});if(data.season?.poster_url)setTmdbPoster('watchlist',data.season.poster_url);if(data.season?.year&&!$('#watchlistYear').value)$('#watchlistYear').value=data.season.year;toast(data.season?.poster_url?'✓ تم جلب بوستر الموسم':'لم يجد TMDB بوسترًا خاصًا لهذا الموسم')}catch(e){console.error(e);toast('تعذر جلب بوستر الموسم')}finally{btn.disabled=false}}

async function compressImage(file,maxW,maxH,quality=.86){return new Promise((resolve,reject)=>{const img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{let w=img.width,h=img.height,s=Math.min(1,maxW/w,maxH/h);w=Math.max(1,Math.round(w*s));h=Math.max(1,Math.round(h*s));const c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(img,0,0,w,h);c.toBlob(b=>{URL.revokeObjectURL(url);b?resolve(b):reject(new Error('compress failed'))},'image/jpeg',quality)};img.onerror=e=>{URL.revokeObjectURL(url);reject(e)};img.src=url})}
async function uploadMedia(file,folder,maxW=1400,maxH=1800){if(!file)return'';if(!CLOUD_READY)return await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});const blob=await compressImage(file,maxW,maxH,.87),path=`${state.currentProfile.id}/${folder}/${uid()}.jpg`;const {error}=await sb.storage.from(MEDIA_BUCKET).upload(path,blob,{contentType:'image/jpeg',upsert:false,cacheControl:'31536000'});if(error)throw error;return sb.storage.from(MEDIA_BUCKET).getPublicUrl(path).data.publicUrl}
function previewInput(input,preview){input.onchange=()=>{const f=input.files?.[0];if(!f){preview.style.display='none';return}preview.src=URL.createObjectURL(f);preview.style.display='block'}}

function openProfileForm(){const p=state.currentProfile;if(!p)return;$('#profileName').value=p.display_name;$('#profileUsername').value=p.username;$('#profileBio').value=p.bio||'';$('#profilePhoto').value='';$('#profilePreview').style.display='none';show('profileModal')}
async function saveProfile(){const p=state.currentProfile;if(!p)return;const name=$('#profileName').value.trim(),username=$('#profileUsername').value.trim().toLowerCase();if(!name||!/^[a-z0-9_]{3,24}$/.test(username))return toast('اسم المستخدم يجب أن يكون 3–24 حرفًا إنجليزيًا/رقمًا/_');const f=$('#profilePhoto').files?.[0];try{const avatar=f?await uploadMedia(f,'avatars',700,700):p.avatar_url,payload={display_name:name,username,bio:$('#profileBio').value.trim(),avatar_url:avatar};if(CLOUD_READY){const {error}=await sb.from('mashhad_profiles').update(payload).eq('id',p.id);if(error)throw error;await loadCloud()}else{Object.assign(p,payload);localSave()}hide('profileModal');renderDashboard();toast('تم حفظ الملف الشخصي')}catch(e){console.error(e);toast(String(e?.message||'تعذر حفظ الملف'))}}
function scoreOptions(v=''){const current=v===null||v===undefined?'':String(v),vals=Array.from({length:19},(_,i)=>10-i*.5);return `<option value="" ${current===''?'selected':''}>— بدون تقييم —</option>`+vals.map(n=>`<option value="${n}" ${Number(current)===n&&current!==''?'selected':''}>${fmtRating(n)}</option>`).join('')}
function renderCriteria(container,preview,values={}){$(container).innerHTML=CRITERIA.map(([k,label])=>`<div class="criterion"><label>${label}</label><select data-criterion="${k}">${scoreOptions(values[k]??'')}</select></div>`).join('');$$(container+' select').forEach(s=>s.onchange=()=>updateCriteriaAvg(container,preview));updateCriteriaAvg(container,preview)}
function updateCriteriaAvg(container,preview){const a=$$(container+' select').map(s=>s.value===''?null:Number(s.value)).filter(Number.isFinite);$(preview).textContent=a.length?fmtRating(a.reduce((x,y)=>x+y,0)/a.length):'—'}
function currentCriteriaValues(viewing){const vals={};if(viewing)viewingRatings(viewing.id).forEach(r=>vals[r.criterion]=Number(r.rating));return vals}
function hasDetailedRatings(viewing){return !!(viewing&&viewingRatings(viewing.id).length)}
function setDetailedMode(toggleId,wrapId,enabled){const t=$(toggleId),w=$(wrapId);if(t)t.checked=!!enabled;if(w)w.classList.toggle('hidden',!enabled)}
function optionalRatingValue(selector){const v=$(selector)?.value;return v===''||v===undefined||v===null?null:Number(v)}
function hasCriteriaValues(container){return $$(container+' select').some(s=>s.value!=='')}
function toggleSeriesFields(kind,prefix){const isSeries=kind==='series';$$(prefix).forEach(e=>e.classList.toggle('hidden',!isSeries))}
function openWorkForm(w=null,fromWatchlist=null){if(!state.currentProfile)return openAuth();pendingWatchlistConvert=fromWatchlist||null;const latest=w?latestViewing(w.id):null;$('#workModalTitle').textContent=w?'تعديل العمل والتقييم الأخير':fromWatchlist?'تحويل من قائمتي القادمة':'إضافة تقييم جديد';$('#workId').value=w?.id||'';$('#workTmdbId').value=w?.tmdb_id||fromWatchlist?.tmdb_id||'';$('#workTmdbType').value=w?.tmdb_media_type||fromWatchlist?.tmdb_media_type||'';$('#workPosterRemote').value=fromWatchlist?.poster_url||'';$('#workTitle').value=w?.title||fromWatchlist?.title||'';$('#workKind').value=w?.kind||fromWatchlist?.kind||'movie';renderWorkGenrePicker(w?workGenres(w):['دراما']);$('#workYear').value=w?.release_year||fromWatchlist?.release_year||new Date().getFullYear();$('#workPlatform').value=sourceCanonical(w?.platform||fromWatchlist?.platform||'');renderWorkSourcePicker($('#workKind').value,w?.platform||fromWatchlist?.platform||'');$('#workStatus').value=w?.status||'completed';$('#workOverride').value=w?.rating_override??'';$('#workNotes').value=w?.notes||'';$('#workPoster').value='';const poster=w?.poster_url||fromWatchlist?.poster_url||'';$('#workPreview').style.display=poster?'block':'none';if(poster)$('#workPreview').src=poster;$('#workTmdbPosterNote')?.classList.toggle('hidden',!(fromWatchlist?.tmdb_id||w?.tmdb_id));$('#workWatchedAt').value=toLocalInput(latest?.watched_at);const plannedSeason=fromWatchlist?.season_number?Number(fromWatchlist.season_number):null;$('#workSeasonsWatched').value=plannedSeason||viewingSeasonCount(latest)||'';$('#workEpisode').value=latest?.episode_number||'';$('#workViewingOverall').value=latest?.overall_rating??'';renderCriteria('#workCriteria','#workAvgPreview',currentCriteriaValues(latest));setDetailedMode('#workDetailedToggle','#workCriteriaWrap',hasDetailedRatings(latest));toggleSeriesFields($('#workKind').value,'.seriesOnly');show('workModal')}async function saveWork(){const id=$('#workId').value,old=state.works.find(w=>w.id===id);if(old&&!canEdit(old))return toast('لا تملك صلاحية التعديل');const title=$('#workTitle').value.trim(),genres=selectedWorkGenres();if(!title||!genres.length)return toast('أدخل اسم العمل واختر تصنيفًا واحدًا على الأقل');const btn=$('#saveWorkBtn');btn.disabled=true;try{const f=$('#workPoster').files?.[0],remotePoster=$('#workPosterRemote').value.trim(),poster=f?await uploadMedia(f,'posters',1200,1800):(remotePoster||old?.poster_url||pendingWatchlistConvert?.poster_url||''),tmdbId=$('#workTmdbId').value?Number($('#workTmdbId').value):null,tmdbType=$('#workTmdbType').value||null,payload={title,kind:$('#workKind').value,genre:genres[0],genres,release_year:$('#workYear').value?Number($('#workYear').value):null,platform:selectedWorkSourceValue(),poster_url:poster,notes:$('#workNotes').value.trim(),rating_override:$('#workOverride').value===''?null:Number($('#workOverride').value),status:$('#workStatus').value,tmdb_id:tmdbId,tmdb_media_type:tmdbType};const detailed=$('#workDetailedToggle').checked,overall=optionalRatingValue('#workViewingOverall');if(overall!==null&&(overall<1||overall>10)){btn.disabled=false;return toast('التقييم يجب أن يكون من 1 إلى 10')}const seriesCount=$('#workKind').value==='series'&&$('#workSeasonsWatched').value?Number($('#workSeasonsWatched').value):null;if($('#workKind').value==='series'&&['completed','watching','dropped'].includes($('#workStatus').value)&&(overall!==null||detailed)&&!seriesCount){btn.disabled=false;return toast('حدد عدد المواسم التي شاهدتها')}if($('#workStatus').value==='completed'&&overall===null&&!(detailed&&hasCriteriaValues('#workCriteria'))&&payload.rating_override===null){btn.disabled=false;return toast('أدخل التقييم النهائي أو أضف تقييمًا مفصلًا')}let workId=id;if(CLOUD_READY){if(id){const {error}=await sb.from('mashhad_works').update(payload).eq('id',id);if(error)throw error}else{const {data,error}=await sb.from('mashhad_works').insert({...payload,owner_id:state.currentProfile.id}).select('id').single();if(error)throw error;workId=data.id}const ownerId=old?.owner_id||state.currentProfile.id;let v=old?latestViewing(workId):null;const vpayload={work_id:workId,owner_id:ownerId,watched_at:new Date($('#workWatchedAt').value||Date.now()).toISOString(),season_number:seriesCount,seasons_watched:seriesCount,episode_number:$('#workKind').value==='series'&&$('#workEpisode').value?Number($('#workEpisode').value):null,status:$('#workStatus').value,notes:'',overall_rating:overall};let viewingId=v?.id;if(viewingId){const {error}=await sb.from('mashhad_viewings').update(vpayload).eq('id',viewingId);if(error)throw error}else{const {data,error}=await sb.from('mashhad_viewings').insert(vpayload).select('id').single();if(error)throw error;viewingId=data.id}await upsertCriteria(workId,viewingId,'#workCriteria',detailed,ownerId);await loadCloud()}else{const now=new Date().toISOString();if(old){Object.assign(old,payload,{updated_at:now});workId=old.id}else{workId=uid();state.works.unshift({id:workId,owner_id:state.currentProfile.id,...payload,created_at:now,updated_at:now})}const ownerId=old?.owner_id||state.currentProfile.id;let v=old?latestViewing(workId):null;if(!v){v={id:uid(),work_id:workId,owner_id:ownerId,created_at:now,updated_at:now};state.viewings.push(v)}Object.assign(v,{watched_at:new Date($('#workWatchedAt').value||Date.now()).toISOString(),season_number:seriesCount,seasons_watched:seriesCount,episode_number:$('#workKind').value==='series'&&$('#workEpisode').value?Number($('#workEpisode').value):null,status:$('#workStatus').value,notes:'',overall_rating:overall,updated_at:now});await upsertCriteria(workId,v.id,'#workCriteria',detailed,ownerId);localSave();renderDashboard()}if(pendingWatchlistConvert?.id){await deleteWatchlistItem(pendingWatchlistConvert.id,true);pendingWatchlistConvert=null}hide('workModal');toast('تم حفظ التقييم')}catch(e){console.error(e);toast('تعذر حفظ التقييم')}finally{btn.disabled=false}}
function openViewingForm(workId,v=null,fromWatchlist=null){const w=state.works.find(x=>x.id===workId);if(!w||!canEdit(w))return;pendingWatchlistViewingConvert=fromWatchlist||null;$('#viewingModalTitle').textContent=v?'تعديل مشاهدة':fromWatchlist?.season_number?`تقييم الموسم ${fromWatchlist.season_number}`:'إضافة مشاهدة جديدة';$('#viewingId').value=v?.id||'';$('#viewingWorkId').value=workId;$('#viewingWatchedAt').value=toLocalInput(v?.watched_at);$('#viewingStatus').value=v?.status||'completed';$('#viewingSeasonsWatched').value=viewingSeasonCount(v)||fromWatchlist?.season_number||'';$('#viewingEpisode').value=v?.episode_number||'';$('#viewingNotes').value=v?.notes||fromWatchlist?.notes||'';$('#viewingOverall').value=v?.overall_rating??'';renderCriteria('#viewingCriteria','#viewingAvgPreview',currentCriteriaValues(v));setDetailedMode('#viewingDetailedToggle','#viewingCriteriaWrap',hasDetailedRatings(v));toggleSeriesFields(w.kind,'.viewingSeriesOnly');show('viewingModal')}
async function saveViewing(){const id=$('#viewingId').value,workId=$('#viewingWorkId').value,w=state.works.find(x=>x.id===workId);if(!w||!canEdit(w))return;const payload={work_id:workId,owner_id:w.owner_id,watched_at:new Date($('#viewingWatchedAt').value||Date.now()).toISOString(),season_number:w.kind==='series'&&$('#viewingSeasonsWatched').value?Number($('#viewingSeasonsWatched').value):null,seasons_watched:w.kind==='series'&&$('#viewingSeasonsWatched').value?Number($('#viewingSeasonsWatched').value):null,episode_number:w.kind==='series'&&$('#viewingEpisode').value?Number($('#viewingEpisode').value):null,status:$('#viewingStatus').value,notes:$('#viewingNotes').value.trim(),overall_rating:optionalRatingValue('#viewingOverall')};const detailed=$('#viewingDetailedToggle').checked,btn=$('#saveViewingBtn');if(payload.overall_rating!==null&&(payload.overall_rating<1||payload.overall_rating>10))return toast('التقييم يجب أن يكون من 1 إلى 10');if(w.kind==='series'&&['completed','watching','dropped'].includes(payload.status)&&(payload.overall_rating!==null||detailed)&&!payload.seasons_watched)return toast('حدد عدد المواسم التي شاهدتها');if(payload.status==='completed'&&payload.overall_rating===null&&!(detailed&&hasCriteriaValues('#viewingCriteria')))return toast('أدخل التقييم النهائي أو أضف تقييمًا مفصلًا');btn.disabled=true;try{let viewingId=id;if(CLOUD_READY){if(id){const {error}=await sb.from('mashhad_viewings').update(payload).eq('id',id);if(error)throw error}else{const {data,error}=await sb.from('mashhad_viewings').insert(payload).select('id').single();if(error)throw error;viewingId=data.id}await upsertCriteria(workId,viewingId,'#viewingCriteria',detailed,w.owner_id);await sb.from('mashhad_works').update({status:payload.status}).eq('id',workId);await loadCloud()}else{const now=new Date().toISOString(),old=state.viewings.find(v=>v.id===id);if(old)Object.assign(old,payload,{updated_at:now});else{viewingId=uid();state.viewings.push({id:viewingId,...payload,created_at:now,updated_at:now})}await upsertCriteria(workId,viewingId,'#viewingCriteria',detailed,w.owner_id);w.status=payload.status;localSave()}if(pendingWatchlistViewingConvert?.id){await deleteWatchlistItem(pendingWatchlistViewingConvert.id,true);pendingWatchlistViewingConvert=null}hide('viewingModal');hide('detailModal');openDetail(workId);toast('تم حفظ المشاهدة')}catch(e){console.error(e);toast('تعذر حفظ المشاهدة')}finally{btn.disabled=false}}
function viewingCard(v,w){const avg=viewingAverage(v),rs=viewingRatings(v.id),manual=v.overall_rating!==null&&v.overall_rating!==undefined&&v.overall_rating!=='';const seasonCtx=w.kind==='series'&&viewingSeasonCount(v)?` · تقييم ${seriesRatingContext(v)}`:'';return `<div class="viewingCard"><div class="viewingHead"><div><b>${dateTimeAr(v.watched_at)}</b><div class="viewingMeta">${statusIcon(v.status)} ${statusName(v.status)}${seasonCtx}${w.kind==='series'&&v.episode_number?` · آخر حلقة ${v.episode_number}`:''}${manual?' · تقييم نهائي':''}</div></div><div class="viewingScore">★ ${avg||avg===0?fmtRating(avg):'—'}</div></div>${v.notes?`<div class="viewingNote">${esc(v.notes)}</div>`:''}${rs.length?`<div class="viewingBreakdown">${rs.map(r=>`<div class="miniCrit"><span>${esc(criterionLabel(r.criterion))}</span><b>${fmtRating(r.rating)}</b></div>`).join('')}</div>`:`<div class="finalOnlyNote">${manual?'تقييم نهائي فقط — بدون تقييمات تفصيلية':'لم تتم إضافة تقييمات تفصيلية'}</div>`}${canEdit(w)?`<div class="viewingActions"><button class="btn secondary" onclick="openViewingForm('${w.id}',state.viewings.find(x=>x.id==='${v.id}'))">تعديل</button><button class="btn danger" onclick="deleteViewing('${v.id}','${w.id}')">حذف المشاهدة</button></div>`:''}</div>`}
function openDetail(id){const w=state.works.find(x=>x.id===id);if(!w)return;const r=finalRating(w),views=workViewings(id),latest=views[0],hasPoster=!!String(w.poster_url||'').trim();const media=hasPoster?`<div class="detailPoster"><img src="${esc(w.poster_url)}" onerror="this.closest('.detailPoster').classList.add('brokenPoster');this.style.display='none'"><button class="close detailClose" onclick="hide('detailModal')">×</button></div>`:`<div class="detailNoPoster"><div class="detailNoPosterMark">K</div><button class="close detailClose" onclick="hide('detailModal')">×</button></div>`;$('#detailContent').innerHTML=`${media}<div class="detailInfo"><div class="detailrow"><div class="detailTitleBlock"><div class="badge">${typeIcon(w.kind)} ${typeName(w.kind)} · ${esc(workGenreText(w))}</div><h2>${esc(w.title)}</h2><div class="detailPills"><span class="statuspill">${w.release_year||'—'}</span> ${w.platform?`<span class="statuspill sourceDetailPill">${sourceBadge(w.platform,'detail')}</span>`:''} <span class="statuspill">${statusName(w.status)}</span> <span class="statuspill">${views.length} مشاهدة</span>${w.kind==='series'&&viewingSeasonCount(latest)?` <span class="statuspill">${esc(seriesRatingContext(latest))}</span>`:''}</div></div><div class="bigscore"><b>${r||r===0?fmtRating(r):'—'}</b></div></div></div>${w.notes?`<div class="reviewbox">${esc(w.notes)}</div>`:''}<div class="sectionhead detailSectionHead" style="margin-top:18px"><div><h3>سجل المشاهدات</h3><p>${latest?`آخر مشاهدة ${dateAr(latest.watched_at)}`:'لا توجد مشاهدة مسجلة'}</p></div>${canEdit(w)?`<button class="btn primary" onclick="openViewingForm('${w.id}')">＋ مشاهدة جديدة</button>`:''}</div>${views.length?views.map(v=>viewingCard(v,w)).join(''):`<div class="empty">لا توجد مشاهدات مسجلة.</div>`}${canEdit(w)?`<div class="detailactions"><button class="btn secondary" onclick="hide('detailModal');openWorkForm(state.works.find(x=>x.id==='${w.id}'))">✎ تعديل العمل</button><button class="btn danger" onclick="deleteWork('${w.id}')">حذف العمل</button></div>`:''}`;show('detailModal')}
async function deleteViewing(id,workId){const v=state.viewings.find(x=>x.id===id),w=state.works.find(x=>x.id===workId);if(!v||!w||!canEdit(w)||!confirm('حذف هذه المشاهدة وتقييمها؟'))return;try{if(CLOUD_READY){const {error}=await sb.from('mashhad_viewings').delete().eq('id',id);if(error)throw error;await loadCloud()}else{state.viewings=state.viewings.filter(x=>x.id!==id);state.ratings=state.ratings.filter(r=>r.viewing_id!==id);localSave()}hide('detailModal');openDetail(workId);toast('تم حذف المشاهدة')}catch(e){console.error(e);toast('تعذر الحذف')}}
async function deleteWork(id){const w=state.works.find(x=>x.id===id);if(!w||!canEdit(w)||!confirm(`حذف «${w.title}» وسجل مشاهداته؟`))return;try{if(CLOUD_READY){const {error}=await sb.from('mashhad_works').delete().eq('id',id);if(error)throw error;await loadCloud()}else{state.works=state.works.filter(x=>x.id!==id);state.viewings=state.viewings.filter(v=>v.work_id!==id);state.ratings=state.ratings.filter(r=>r.work_id!==id);localSave()}hide('detailModal');renderDashboard();toast('تم حذف العمل')}catch(e){console.error(e);toast('تعذر الحذف')}}

async function adminCall(body){const session=(await sb.auth.getSession()).data.session;if(!session)throw new Error('NO_SESSION');const r=await fetch(ADMIN_USERS_ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json','apikey':SUPABASE_KEY,'Authorization':`Bearer ${session.access_token}`},body:JSON.stringify(body)}),data=await r.json().catch(()=>({}));if(!r.ok||!data.ok)throw new Error(data.error||'REQUEST_FAILED');return data}
async function createUser(){if(!isAdmin())return;const body={action:'create',display_name:$('#adminNewDisplayName').value.trim(),username:$('#adminNewUsername').value.trim().toLowerCase(),email:$('#adminNewEmail').value.trim().toLowerCase(),password:$('#adminNewPassword').value};if(!body.display_name||!/^[a-z0-9_]{3,24}$/.test(body.username)||!body.email||body.password.length<8)return toast('أكمل البيانات وتأكد أن كلمة المرور 8 أحرف على الأقل');const b=$('#adminCreateUserBtn');b.disabled=true;try{if(CLOUD_READY){await adminCall(body);await loadCloud()}else{if(state.profiles.some(p=>p.username===body.username))throw new Error('USERNAME_TAKEN');state.profiles.push({id:uid(),username:body.username,public_slug:body.username+'-cinema',display_name:body.display_name,bio:'',avatar_url:'',role:'creator',is_active:true,created_at:new Date().toISOString(),password:body.password});localSave();renderAdmin()}hide('adminCreateUserModal');toast('تم إنشاء الحساب')}catch(e){console.error(e);toast(e.message==='USERNAME_TAKEN'?'اسم المستخدم مستخدم':e.message==='EMAIL_TAKEN'?'البريد مستخدم بالفعل':'تعذر إنشاء الحساب')}finally{b.disabled=false}}
async function toggleUser(id,active){if(!isAdmin())return;try{if(CLOUD_READY){await adminCall({action:'set-active',user_id:id,is_active:active});await loadCloud()}else{const p=state.profiles.find(x=>x.id===id);if(p)p.is_active=active;localSave();renderAdmin()}toast(active?'تم تفعيل المستخدم':'تم إيقاف المستخدم')}catch(e){console.error(e);toast('تعذر تعديل الحساب')}}
function openResetPassword(id){if(!isAdmin())return;$('#resetUserId').value=id;$('#resetPasswordValue').value='';show('resetPasswordModal')}
async function resetPassword(){const id=$('#resetUserId').value,password=$('#resetPasswordValue').value;if(password.length<8)return toast('كلمة المرور 8 أحرف على الأقل');try{if(CLOUD_READY)await adminCall({action:'reset-password',user_id:id,password});else{const p=state.profiles.find(x=>x.id===id);if(p)p.password=password;localSave()}hide('resetPasswordModal');toast('تم تعيين كلمة المرور الجديدة')}catch(e){console.error(e);toast('تعذر إعادة تعيين كلمة المرور')}}

function openSettings(){const p=state.currentProfile;if(!p)return openAuth();$('#publicLinkPreview').value=visualShareUrl(p);$('#publicSlugInput').value=p.public_slug||p.username||'';$('#ownerAppLinkBlock').classList.toggle('hidden',!isAdmin());$('#settingsAdminBtn').classList.toggle('hidden',!isAdmin());$('#ownerAppLinkPreview').value=`${location.origin}/KADR/`;$('#tmdbOwnerConfig')?.classList.toggle('hidden',!isAdmin());show('settingsModal');refreshTmdbStatus()}
async function savePublicSlug(){const p=state.currentProfile,slug=$('#publicSlugInput').value.trim().toLowerCase();if(!p)return;if(!/^[a-z0-9][a-z0-9_-]{2,38}[a-z0-9]$/.test(slug))return toast('استخدم 4–40 حرفًا: a-z و0-9 و- و_');try{if(CLOUD_READY){const {error}=await sb.from('mashhad_profiles').update({public_slug:slug}).eq('id',p.id);if(error)throw error;await loadCloud()}else{p.public_slug=slug;localSave()}openSettings();toast('تم تحديث الرابط الشخصي')}catch(e){console.error(e);toast('الاسم مستخدم أو غير صالح')}}
async function copyText(t){try{await navigator.clipboard.writeText(t);toast('تم النسخ')}catch{const i=document.createElement('textarea');i.value=t;document.body.appendChild(i);i.select();document.execCommand('copy');i.remove();toast('تم النسخ')}}
async function copyProfile(id){const p=profileByKey(id);if(p)await copyText(shareUrl(p))}
async function shareProfile(id){const p=profileByKey(id);if(!p)return;const url=shareUrl(p);try{if(navigator.share){await navigator.share({title:`تقييمات ${p.display_name} على كادر`,text:'شاهد تقييماتي للأفلام والمسلسلات على كادر',url});return}await copyText(url)}catch(e){if(e?.name!=='AbortError')toast('تعذر فتح المشاركة')}}


function myFollow(targetId){return state.follows.find(f=>f.follower_id===state.currentProfile?.id&&f.following_id===targetId)||null}
function incomingFollowerCount(id){return state.follows.filter(f=>f.following_id===id).length}
function followingCount(id){return state.follows.filter(f=>f.follower_id===id).length}
function unreadSocialCount(){return state.socialNotifications.filter(n=>!n.read_at).length}
function refreshCommunityBadge(){const n=unreadSocialCount(),b=$('#communityBadge'),t=$('#communityTabBadge'),btn=$('#communityBtn');btn?.classList.toggle('hidden',!state.currentProfile);for(const el of [b,t])if(el){el.textContent=String(n);el.classList.toggle('hidden',!n)}}
function followActionsHtml(p){const f=myFollow(p.id);if(!f)return `<button class="btn primary followBtn" onclick="toggleFollow('${p.id}',event)">＋ متابعة</button>`;return `<button class="btn secondary followBtn following" onclick="toggleFollow('${p.id}',event)">✓ أتابعه</button><button class="btn ${f.notify_new_works?'primary':'secondary'} bellFollowBtn" onclick="toggleFollowNotify('${p.id}',event)" title="إشعار عند إضافة عمل جديد">${f.notify_new_works?'🔔 التنبيه مفعل':'🔕 فعّل التنبيه'}</button>`}
function personRow(p){const f=myFollow(p.id),works=profileWorks(p.id).length;return `<div class="personRow"><button class="personIdentity" onclick="hide('communityModal');setRoute({u:'${esc(p.username)}'})"><img src="${esc(p.avatar_url||avatarPlaceholder(p.display_name))}" onerror="this.src='${avatarPlaceholder(p.display_name)}'"><span><b>${esc(p.display_name)}</b><small dir="ltr">@${esc(p.username)}</small><em>${works} عمل</em></span></button><div class="personActions">${f?`<button class="iconToggle ${f.notify_new_works?'active':''}" onclick="toggleFollowNotify('${p.id}',event)" title="إشعار عند إضافة عمل">${f.notify_new_works?'🔔':'🔕'}</button>`:''}<button class="btn ${f?'secondary':'primary'} compactBtn" onclick="toggleFollow('${p.id}',event)">${f?'✓ أتابعه':'＋ متابعة'}</button></div></div>`}
function renderCommunityDiscover(){const q=String($('#communitySearchInput')?.value||'').trim().toLowerCase(),me=state.currentProfile?.id;let users=state.profiles.filter(p=>p.id!==me&&p.is_active!==false);if(q)users=users.filter(p=>String(p.username||'').toLowerCase().includes(q)||String(p.display_name||'').toLowerCase().includes(q));else users=users.slice(0,12);$('#communitySearchResults').innerHTML=users.length?users.slice(0,30).map(personRow).join(''):`<div class="empty compactEmpty">لا يوجد مستخدم بهذا الاسم.</div>`}
function renderFollowingList(){const ids=state.follows.filter(f=>f.follower_id===state.currentProfile?.id).map(f=>f.following_id),users=ids.map(id=>state.profiles.find(p=>p.id===id)).filter(Boolean);$('#followingList').innerHTML=users.length?users.map(personRow).join(''):`<div class="empty compactEmpty">لا تتابع أحدًا بعد. ابحث عن أصدقائك من تبويب «اكتشف».</div>`}
function socialNotificationRow(n){const actor=state.profiles.find(p=>p.id===n.actor_id),work=state.works.find(w=>w.id===n.work_id);return `<button class="socialNotification ${n.read_at?'':'unread'}" onclick="openSocialNotification('${n.id}')"><img src="${esc(actor?.avatar_url||avatarPlaceholder(actor?.display_name||'K'))}" onerror="this.src='${avatarPlaceholder(actor?.display_name||'K')}'"><span><b>${esc(n.title)}</b><small>${esc(n.body)}</small><em>${dateTimeAr(n.created_at)}</em></span>${work?.poster_url?`<img class="notificationPoster" src="${esc(work.poster_url)}">`:''}</button>`}
function renderSocialNotifications(){const list=state.socialNotifications;$('#socialNotificationsList').innerHTML=list.length?list.map(socialNotificationRow).join(''):`<div class="empty compactEmpty">لا توجد إشعارات متابعة حتى الآن.</div>`;refreshCommunityBadge()}
function renderCommunity(){const tab=state.communityTab||'discover';$$('[data-community-tab]').forEach(b=>b.classList.toggle('active',b.dataset.communityTab===tab));$('#communityDiscover').classList.toggle('hidden',tab!=='discover');$('#communityFollowing').classList.toggle('hidden',tab!=='following');$('#communityNotifications').classList.toggle('hidden',tab!=='notifications');if(tab==='discover')renderCommunityDiscover();if(tab==='following')renderFollowingList();if(tab==='notifications')renderSocialNotifications();refreshCommunityBadge()}
function openCommunity(tab='discover'){if(!state.currentProfile)return openAuth();state.communityTab=tab;show('communityModal');renderCommunity();setTimeout(()=>tab==='discover'&&$('#communitySearchInput')?.focus(),100)}
async function reloadSocialState(){if(!CLOUD_READY||!state.currentProfile)return;const [{data:follows,error:fe},{data:notes,error:ne}]=await Promise.all([sb.from('mashhad_follows').select('*').order('created_at',{ascending:false}),sb.from('mashhad_social_notifications').select('*').order('created_at',{ascending:false}).limit(100)]);if(fe||ne){console.warn(fe||ne);return}state.follows=follows||[];state.socialNotifications=notes||[];refreshCommunityBadge();if($('#communityModal')?.classList.contains('show'))renderCommunity()}
async function toggleFollow(targetId,event){event?.stopPropagation();if(!state.currentProfile)return openAuth();const f=myFollow(targetId);try{if(f){const {error}=await sb.from('mashhad_follows').delete().eq('follower_id',state.currentProfile.id).eq('following_id',targetId);if(error)throw error;toast('تم إلغاء المتابعة')}else{const {error}=await sb.from('mashhad_follows').insert({follower_id:state.currentProfile.id,following_id:targetId,notify_new_works:false});if(error)throw error;toast('تمت المتابعة')};await reloadSocialState();if(state.viewProfile?.id===targetId)renderPublic()}catch(e){console.error(e);toast('تعذر تعديل المتابعة')}}
async function toggleFollowNotify(targetId,event){event?.stopPropagation();const f=myFollow(targetId);if(!f)return toast('تابع المستخدم أولًا');const next=!f.notify_new_works;try{const {error}=await sb.from('mashhad_follows').update({notify_new_works:next}).eq('follower_id',state.currentProfile.id).eq('following_id',targetId);if(error)throw error;await reloadSocialState();if(state.viewProfile?.id===targetId)renderPublic();if(next){if(Notification.permission==='granted')await ensurePushSubscriptionRegistered({createIfMissing:true});else toast('تم تفعيل التنبيه داخل KADR — فعّل إشعارات الجهاز ليصلك خارجه')}else toast('تم إيقاف تنبيهات هذا المستخدم')}catch(e){console.error(e);toast('تعذر تعديل التنبيه')}}
async function openSocialNotification(id){const n=state.socialNotifications.find(x=>x.id===id);if(!n)return;if(!n.read_at){const now=new Date().toISOString();n.read_at=now;refreshCommunityBadge();sb.from('mashhad_social_notifications').update({read_at:now}).eq('id',id).then(()=>{}).catch(console.warn)}const actor=state.profiles.find(p=>p.id===n.actor_id);hide('communityModal');if(actor)setRoute({u:actor.username,work:n.work_id})}
async function markAllSocialRead(){const unread=state.socialNotifications.filter(n=>!n.read_at);if(!unread.length)return toast('كل الإشعارات مقروءة');const now=new Date().toISOString();try{const {error}=await sb.from('mashhad_social_notifications').update({read_at:now}).eq('recipient_id',state.currentProfile.id).is('read_at',null);if(error)throw error;unread.forEach(n=>n.read_at=now);renderSocialNotifications();toast('تم تحديد الكل كمقروء')}catch(e){console.error(e);toast('تعذر تحديث الإشعارات')}}

function openReleaseForm(){if(!isAdmin())return;const n=versionNumber(state.release?.stable_version||'1.0');$('#releaseVersion').value=(Math.round((n+.1)*10)/10).toFixed(1);$('#releaseNotes').value='';show('releaseModal')}
async function releaseCall(body,{retries=1}={}){const session=(await sb.auth.getSession()).data.session;if(!session)throw Object.assign(new Error('NO_SESSION'),{code:'NO_SESSION'});let last;for(let attempt=0;attempt<=retries;attempt++){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),18000);try{const r=await fetch(RELEASE_ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json','apikey':SUPABASE_KEY,'Authorization':`Bearer ${session.access_token}`},body:JSON.stringify(body),signal:controller.signal}),data=await r.json().catch(()=>({}));clearTimeout(timer);if(!r.ok||!data.ok){const e=new Error(data.detail||data.error||'REQUEST_FAILED');e.code=data.error||'REQUEST_FAILED';e.detail=data.detail||'';const retry409=r.status===409&&['GITHUB_NOT_READY','CANDIDATE_NOT_READY','CANDIDATE_NOT_TESTED'].includes(String(data.error||''));if((r.status<500&&!retry409)||attempt===retries)throw e;last=e}else{return data}}catch(e){clearTimeout(timer);last=e;if(attempt===retries)throw e;await new Promise(r=>setTimeout(r,650*(attempt+1)))}}throw last||new Error('REQUEST_FAILED')}
function openCandidateBuild(){const version=String(state.release?.candidate_version||BUILD_VERSION);localStorage.setItem(CANDIDATE_TEST_KEY,version);localStorage.setItem(CANDIDATE_ACK_KEY,version);$('#updateNotice')?.classList.add('hidden');state.pendingUpdate=null;clearKadrNotifications();const path=String(state.release?.candidate_path||'candidate'),v=encodeURIComponent(version),stamp=Date.now();location.href=path==='root'||path==='release'?`/KADR/?candidateTest=1&candidateVersion=${v}&forceUpdate=1&_=${stamp}`:`/KADR/candidate/?candidateTest=1&candidateVersion=${v}&_=${stamp}`}
function returnToMyHome(){setRoute({})}
async function markCandidateTested({silent=false}={}){if(!CLOUD_READY||!isAdmin()||!candidateMode()||candidateTestInFlight)return false;if(state.release?.candidate_status!=='testing')return !!state.release?.candidate_tested_at;if(state.release?.candidate_tested_at){localStorage.removeItem(CANDIDATE_TEST_KEY);$('#updateNotice')?.classList.add('hidden');state.pendingUpdate=null;await clearKadrNotifications();returnToMyHome();return true}candidateTestInFlight=true;try{const version=String(state.release.candidate_version);localStorage.setItem(CANDIDATE_TEST_KEY,version);localStorage.setItem(CANDIDATE_ACK_KEY,version);await releaseCall({action:'mark-tested',version},{retries:3});const rel=await refreshReleaseState();if(!rel?.candidate_tested_at)throw Object.assign(new Error('TEST_STATE_NOT_CONFIRMED'),{code:'TEST_STATE_NOT_CONFIRMED'});localStorage.removeItem(CANDIDATE_TEST_KEY);$('#updateNotice')?.classList.add('hidden');state.pendingUpdate=null;await clearKadrNotifications();returnToMyHome();if(!silent)toast('✓ تم تسجيل مراجعة النسخة — يمكنك اعتمادها من إدارة كادر');return true}catch(e){console.error(e);if(!silent)toast(e.code==='CANDIDATE_CHANGED_RETEST'?'تغيّرت ملفات التحديث أثناء الاختبار؛ أعد فتح النسخة الجديدة':'تعذر تأكيد المراجعة — حاول مرة واحدة من الزر');return false}finally{candidateTestInFlight=false}}
async function stageRelease(btn=null){if(!isAdmin()||releaseActionInFlight)return;const version=$('#releaseVersion').value.trim(),notes=$('#releaseNotes').value.trim();if(!/^\d+(\.\d+){1,2}$/.test(version)||versionNumber(version)<=versionNumber(state.release.stable_version))return toast('أدخل رقم إصدار أعلى من الحالي');releaseActionInFlight=true;releaseBusy(btn||$('#stageReleaseBtn'),true,'جارٍ التحقق…');try{await releaseCall({action:'stage',version,notes,scope:'release'},{retries:2});hide('releaseModal');await waitForReleaseState(r=>r.candidate_available&&String(r.candidate_version)===version&&r.candidate_files_verified,9000);renderAdmin();toast(`✓ v${version} وصل للمالك وجاهز للاختبار`)}catch(e){console.error(e);toast(e.code==='GITHUB_NOT_READY'?'ملفات الإصدار غير مكتملة في GitHub — لم يُرسل أي إشعار':'تعذر تهيئة التحديث')}finally{releaseActionInFlight=false;releaseBusy(btn||$('#stageReleaseBtn'),false)}}
async function approveCandidateRelease(btn=null){if(!isAdmin()||!state.release?.candidate_available||releaseActionInFlight)return;if(!candidateMode()&&!state.release?.candidate_tested_at)return toast('افتح النسخة التجريبية أولًا');if(!state.release?.candidate_tested_at){const ok=await markCandidateTested({silent:true});if(!ok){await refreshReleaseState().catch(()=>{});renderAdmin();return toast('تعذر تأكيد الاختبار تلقائيًا؛ اضغط «تأكيد الاختبار» مرة واحدة')}}const version=String(state.release.candidate_version);releaseActionInFlight=true;releaseBusy(btn,true,'جارٍ الاعتماد والنشر…');try{const data=await releaseCall({action:'approve',version},{retries:2});if(data.published){state.release={...state.release,stable_version:version,candidate_available:false,candidate_status:'published'};localStorage.removeItem(CANDIDATE_TEST_KEY);localStorage.removeItem(CANDIDATE_ACK_KEY);renderAdmin();refreshReleaseUI();toast(`✓ تم اعتماد ونشر v${version} للمستخدمين`)}else{state.release={...state.release,candidate_status:'approved_waiting_publish'};renderAdmin();toast(`✓ تم اعتماد v${version} — جارٍ النشر التلقائي`);const done=await waitForReleaseState(r=>String(r.stable_version)===version&&!r.candidate_available,90000);if(String(done?.stable_version)===version&&!done?.candidate_available){renderAdmin();refreshReleaseUI();toast(`✓ تم نشر v${version} للمستخدمين تلقائيًا`)}else{renderAdmin();toast('تم الاعتماد بنجاح — سيكتمل النشر تلقائيًا دون ضغط إضافي')}}}catch(e){console.error(e);if(e.code==='CANDIDATE_CHANGED_RETEST'){await refreshReleaseState().catch(()=>{});renderAdmin();toast('تغيّرت ملفات GitHub بعد الاختبار؛ يجب فتح النسخة الجديدة مرة واحدة')}else if(e.code==='CANDIDATE_NOT_TESTED'){await refreshReleaseState().catch(()=>{});renderAdmin();toast('لم يثبت الخادم الاختبار بعد؛ اضغط تأكيد الاختبار مرة واحدة')}else toast('تعذر اعتماد التحديث الآن')}finally{releaseActionInFlight=false;releaseBusy(btn,false)}}
async function publishApprovedRelease(btn=null){if(!isAdmin()||releaseActionInFlight)return;const version=String(state.release?.candidate_version||'');if(!confirm(`نشر v${version} للمستخدمين بعد التحقق النهائي من GitHub؟`))return;releaseActionInFlight=true;releaseBusy(btn,true,'جارٍ النشر…');try{const data=await releaseCall({action:'publish'},{retries:2});await waitForReleaseState(r=>String(r.stable_version)===String(data.version)&&!r.candidate_available,10000);localStorage.setItem(UPDATE_ACCEPTED_KEY,String(data.version));renderAdmin();toast(`✓ تم نشر v${data.version}`)}catch(e){console.error(e);toast(e.code==='GITHUB_CHANGED_AFTER_APPROVAL'?'تغيّرت الملفات بعد الاعتماد؛ تم إيقاف النشر لحمايتك':'تعذر نشر التحديث')}finally{releaseActionInFlight=false;releaseBusy(btn,false)}}

